using System;
using UnityEngine;

public enum GardenInputMode { Unknown, Hands, Controllers }
public enum GardenControlDemo { None, Move, Grab, Calendar, CalendarSelect, Water, Upright, WateringGrab }
public enum GardenDemoPose { Open, Pinch, Curled, Point, ThumbFree }

/// <summary>References the original audio and Meta visual assets without moving or duplicating them.</summary>
[CreateAssetMenu(menuName = "Garden/Gronny audio catalogue")]
public sealed class GronnyAudioCatalogue : ScriptableObject
{
    [Serializable]
    public sealed class Cue
    {
        public string id;
        public AudioClip clip;
        public GardenInputMode mode;
        public GardenControlDemo demo;
        [Min(0)] public int priority;
        [Range(0f, 1f)] public float volume = 1f;
        [Min(0f)] public float cooldown = 30f;
        public bool assisted;
        public string controllerTarget;
        public bool rightHand;
        public AnimationClip controllerAnimation;
        [TextArea] public string transcript;
        public Step[] steps = Array.Empty<Step>();
    }

    [Serializable]
    public sealed class Step
    {
        [Min(0f)] public float at;
        public GardenDemoPose pose;
        public Vector3 position;
        public Vector3 rotation;
        public Vector3 thumbRotation;
        [Range(0f, 1f)] public float thumbSwipeProgress;
        [Range(0f, 1f)] public float thumbSwipeWeight;
        public string label;
        [Range(0f, 1f)] public float press;
    }

    [Serializable]
    public sealed class HandVisual
    {
        public GameObject prefab;
        public string animationRoot;
        public AnimationClip pinch;
        public AnimationClip curled;
        public AnimationClip point;
        public AnimationClip thumbFree;
        [Tooltip("Thumb pad slides along the curled index. Clip start is back; clip end is forward.")]
        public AnimationClip thumbSwipe;
    }

    public Cue[] cues = Array.Empty<Cue>();
    [HideInInspector] public int waterSavingAudioVersion;
    public HandVisual leftHand = new();
    public HandVisual rightHand = new();
    public GameObject leftController;
    public GameObject rightController;
    public AnimationClip controllerStick;
    public AnimationClip controllerGrip;
    public AnimationClip controllerY;
    public AnimationClip controllerTrigger;
    public Material demonstrationMaterial;
    [Header("Playback")]
    [Range(0f, 1f)] public float voiceVolume = 0.85f;
    [Range(0.75f, 1.25f)] public float pitch = 1f;
    [Min(0f)] public float gapSeconds = 0.35f;
    [Header("Progressive help")]
    [Min(5f)] public float idleHelpSeconds = 30f;
    [Min(5f)] public float independentHelpSeconds = 55f;
    [Header("VR presentation")]
    public Vector3 viewOffset = new(0.34f, -0.18f, 0.85f);
    public Vector3 handEulerAngles = new(0f, 90f, -75f);
    public Vector3 controllerEulerAngles = new(65f, 180f, 0f);
    [Range(0.5f, 2f)] public float visualScale = 1.15f;
    [Min(0.01f)] public float blendSeconds = 0.35f;
    [Header("Hand teaching pace")]
    [Min(1f)] public float handPoseHoldSeconds = 2.5f;
    [Min(0.1f)] public float handPoseBlendSeconds = 0.7f;

    public Cue Find(string id) => Array.Find(cues, cue => cue != null && cue.id == id);

    // Original IDs now point to the replacement WAVs supplied for the water-saving lesson.
    public Cue FindTutorialCue(string id) => Find(id);
}

using System.Collections;
using System.Collections.Generic;
using Oculus.Interaction;
using Oculus.Interaction.Grab;
using Oculus.Interaction.HandGrab;
using Oculus.Interaction.Locomotion;
using UnityEngine;

public enum GardenTutorialAction { Plant, Pour, OpenCalendar, Advance, Refill, RefillWithController, Recover, Restart, CloseCalendar }

/// <summary>Unlocks the first tomato instructions after the player completes each action.</summary>
[DisallowMultipleComponent]
[DefaultExecutionOrder(100)]
public sealed class GronnyTutorial : MonoBehaviour
{
    [SerializeField] private GronnyAudioCatalogue catalogue;
    [SerializeField, TextArea] private string seedPlantingInstruction = "Pick me and plant me\non the plant pot";
    private SeedsController seeds;
    private CalendarSystem calendar;
    private CalendarVisibilityController visibility;
    private CalendarPanel panel;
    private FirstPersonLocomotor[] locomotors;
    private WateringCan[] cans;
    private SeedItem[] seedItems;
    private GronnyVoicePlayer voice;
    private GardenControlDemonstration demonstration;
    private readonly HashSet<string> learned = new();
    private readonly HashSet<int> heldObjects = new();
    private GardenInputMode mode;
    private GardenInputMode candidateMode;
    private float modeChangedAt;
    private float lastActionAt;
    private float lastWater;
    private float nextRefresh;
    private int phase = -2;
    private bool wasExcess;
    private bool completed;
    private bool initialized;
    private bool subscribed;
    private enum GuideStep { Move, Grab, Plant, Water, Calendar, CalendarSelect, Free }
    private static GronnyTutorial active;
    private readonly HashSet<Behaviour> blockedInteractions = new();
    private float nextInteractionRefresh;
    private Transform playerOrigin;
    private Vector3 movementStart;
    private bool movementRequested;
    private bool movementPracticeStarted;
    private WateringCan refillCan;
    private Transform viewer;
    private TextMesh seedPlantingCaption;
    private bool grabInstructionFinished;
    private int announcedWaterAttempt;

    private GuideStep Step
    {
        get
        {
            if (!Learned("move")) return GuideStep.Move;
            if (!Learned("grab")) return GuideStep.Grab;
            if (State == null) return GuideStep.Plant;
            if (State.tomatoPhase > 0) return GuideStep.Free;
            bool open = visibility != null && visibility.IsVisible;
            if (CanEmpty) return open && Learned("calendar") ? GuideStep.CalendarSelect : GuideStep.Calendar;
            if (!Ready) return GuideStep.Water;
            if (Learned("calendar") && Learned("calendar_select")) return GuideStep.Free;
            return open && Learned("calendar") ? GuideStep.CalendarSelect : GuideStep.Calendar;
        }
    }

    public static bool Allows(GardenTutorialAction action)
    {
        if (GardenMenuController.GardenSuspended) return false;
        if (GardenWaterSupply.Active != null && GardenWaterSupply.Active.Exhausted)
            return action == GardenTutorialAction.OpenCalendar || action == GardenTutorialAction.CloseCalendar ||
                action == GardenTutorialAction.Restart || action == GardenTutorialAction.Recover;
        if (active == null || !active.Running) return true;
        GuideStep step = active.Step;
        if (step == GuideStep.Free) return true;
        return action switch
        {
            GardenTutorialAction.Plant => step == GuideStep.Plant,
            GardenTutorialAction.Pour => step == GuideStep.Water,
            GardenTutorialAction.OpenCalendar => step == GuideStep.Calendar || step == GuideStep.CalendarSelect,
            GardenTutorialAction.Advance => step == GuideStep.CalendarSelect && active.Ready && !active.CanEmpty,
            GardenTutorialAction.Refill => step == GuideStep.CalendarSelect && active.CanEmpty,
            _ => false
        };
    }

    // SeedItem detects release before its planting attempt, including grabs shorter than the polling interval.
    public static void RecordSeedRelease(SeedItem seed)
    {
        if (GardenMenuController.GardenSuspended) return;
        if (active != null && active.Running && active.Step == GuideStep.Grab &&
            seed != null && seed.Crop == SeedCrop.Tomato) active.Learn("grab");
    }

    public bool TryGetInstruction(out string text, out string detail)
    {
        text = detail = null;
        if (!Running || Step == GuideStep.Free) return false;
        bool hands = mode == GardenInputMode.Hands;
        (text, detail) = Step switch
        {
            GuideStep.Move => ("Step 1/6: Practice moving.", mode == GardenInputMode.Unknown
                ? "Use your tracked hands or Touch controllers to begin."
                : hands ? "Curl your index finger, tap your thumb, then swipe to step." : "Move with the left joystick."),
            GuideStep.Grab => ("Step 2/6: Pick up and release the seed labelled Tomato.",
                hands ? "Pinch to grab. Open your fingers to release." : "Hold Grip to grab. Release Grip to let go."),
            GuideStep.Plant => ("Step 3/6: Plant the seed labelled Tomato.", "Drop it onto the soil in an empty small pot."),
            GuideStep.Water => (Excess ? "Step 4/6: Stop watering and wait for drainage."
                : !NeedsWater ? "Step 4/6: Hold the watering can upright."
                : "Step 4/6: Water the soil near the roots.", "Reach the water target, then stop pouring."),
            GuideStep.Calendar => ("Step 5/6: Open the calendar.",
                hands ? "Pinch with your left hand away from objects." : "Press Y on the left controller."),
            _ => (CanEmpty ? "Step 6/6: Select Refill water." : "Step 6/6: Select Advance phase.",
                hands ? "Point at the button and pinch." : "Aim at the button and press Trigger.")
        };
        return true;
    }

    private SeedsController.PlantedSeed Plant => seeds != null ? seeds.PrototypeTomato : null;
    private CalendarSystem.PlantSave State => seeds != null ? seeds.GetState(Plant) : null;
    private bool Running => initialized && isActiveAndEnabled && !completed &&
        seeds != null && seeds.isActiveAndEnabled && calendar != null;
    private bool Caring => Running && State != null && State.tomatoPhase < 5 && !calendar.IsAdvancing &&
        (GardenWaterSupply.Active == null || !GardenWaterSupply.Active.Exhausted);
    private bool Excess => Caring && State.retainedWaterMillilitres > seeds.ExcessLimit(Plant);
    private bool NeedsWater => Caring && seeds.TargetMillilitres(Plant) > 0f &&
        State.retainedWaterMillilitres < seeds.TargetMillilitres(Plant);
    private bool Ready => Caring && !NeedsWater && !Excess &&
        seeds.TargetMillilitres(Plant) > 0f && Time.unscaledTime - State.lastWaterAt >= 0.5f &&
        !System.Array.Exists(cans, can => can != null && can.IsHeld && can.IsTiltedToPour);
    private bool CanEmpty => cans != null && System.Array.Exists(cans,
        can => can != null && can.isActiveAndEnabled && (can.IsHeld || can == refillCan) && can.CurrentWaterLitres <= 0f);
    private bool ShowWateringDemonstration => Caring && phase == 0 && Step == GuideStep.Water &&
        NeedsWater && !Excess && !CanEmpty;

    private IEnumerator Start()
    {
        // The welcome and progressive locks start only after Play and a released UI selection.
        while (!GardenMenuController.HasStarted || GardenMenuController.GardenSuspended) yield return null;
        if (catalogue == null) catalogue = Resources.Load<GronnyAudioCatalogue>("GronnyAudio/Tutorial");
        seeds = FindFirstObjectByType<SeedsController>();
        calendar = seeds != null ? seeds.Calendar : null;
        if (catalogue == null || calendar == null)
        {
            Debug.LogError("Gronny tutorial needs its audio catalogue and the existing tomato calendar.", this);
            enabled = false;
            yield break;
        }
        visibility = FindFirstObjectByType<CalendarVisibilityController>();
        if (visibility != null) visibility.Close();
        panel = FindFirstObjectByType<CalendarPanel>(FindObjectsInactive.Include);
        cans = FindObjectsByType<WateringCan>(FindObjectsSortMode.None);
        seedItems = FindObjectsByType<SeedItem>(FindObjectsSortMode.None);
        locomotors = FindObjectsByType<FirstPersonLocomotor>(FindObjectsSortMode.None);
        OVRCameraRig rig = FindFirstObjectByType<OVRCameraRig>();
        if (visibility == null || panel == null || rig == null || locomotors.Length == 0)
        {
            Debug.LogError("Gronny's progressive tutorial needs the Meta camera rig, locomotion and calendar controls.", this);
            enabled = false;
            yield break;
        }
        demonstration = gameObject.AddComponent<GardenControlDemonstration>();
        Transform gardeningAnchor = GetComponent<TomatoPrototypeGuide>()?.GardeningDemonstrationAnchor;
        demonstration.Configure(catalogue, gardeningAnchor);
        voice = gameObject.AddComponent<GronnyVoicePlayer>();
        voice.Configure(catalogue, demonstration);
        voice.SetBackgroundDemonstration("04_first_watering", () => ShowWateringDemonstration);
        initialized = true;
        active = this;
        playerOrigin = rig.transform;
        viewer = rig.centerEyeAnchor;
        movementStart = playerOrigin.position;
        if (GardenMenuController.StartsAtPlanting)
        {
            learned.Add("move");
            learned.Add("grab");
            grabInstructionFinished = true;
        }
        RefreshInteractionLocks();
        lastActionAt = Time.unscaledTime;
        Subscribe();
        if (!GardenMenuController.StartsAtPlanting)
            Say("01_welcome", "welcome-start", () => Running);
        RefreshPhase();
    }

    private void OnEnable()
    {
        if (!initialized) return;
        voice.enabled = true;
        active = this;
        RefreshInteractionLocks();
        Subscribe();
        lastActionAt = Time.unscaledTime;
        QueueControls();
    }

    private void Subscribe()
    {
        if (subscribed || completed) return;
        voice.AudioFinished += OnAudioFinished;
        seeds.PlantingRejected += OnPlantingRejected;
        calendar.AdvanceBlocked += OnAdvanceBlocked;
        if (visibility != null)
        {
            visibility.VisibilityChanged += OnCalendarVisible;
        }
        if (panel != null) panel.ActionCompleted += OnCalendarAction;
        foreach (FirstPersonLocomotor locomotor in locomotors)
            if (locomotor != null) locomotor.WhenLocomotionEventHandled += OnMoved;
        subscribed = true;
    }

    private void Unsubscribe()
    {
        if (!subscribed) return;
        if (voice != null) voice.AudioFinished -= OnAudioFinished;
        if (seeds != null) seeds.PlantingRejected -= OnPlantingRejected;
        if (calendar != null) calendar.AdvanceBlocked -= OnAdvanceBlocked;
        if (visibility != null)
        {
            visibility.VisibilityChanged -= OnCalendarVisible;
        }
        if (panel != null) panel.ActionCompleted -= OnCalendarAction;
        foreach (FirstPersonLocomotor locomotor in locomotors)
            if (locomotor != null) locomotor.WhenLocomotionEventHandled -= OnMoved;
        subscribed = false;
    }

    private void Update()
    {
        if (GardenMenuController.GardenSuspended)
        {
            lastActionAt = Time.unscaledTime;
            heldObjects.Clear();
            movementRequested = false;
            if (playerOrigin != null) movementStart = playerOrigin.position;
            return;
        }
        if (!Running)
        {
            if (initialized && !completed) voice.Clear();
            if (blockedInteractions.Count > 0) ReleaseInteractionLocks();
            return;
        }
        UpdateMode();
        foreach (WateringCan can in cans)
            if (can != null && can.IsHeld && can.CurrentWaterLitres <= 0f) refillCan = can;
        if (Step == GuideStep.Water && System.Array.Exists(cans, can => can != null && can.IsHeld)) Learn("watering_grab");
        ObserveGrabs();
        if (Step == GuideStep.Move && movementPracticeStarted && movementRequested && playerOrigin != null &&
            Vector3.ProjectOnPlane(playerOrigin.position - movementStart, Vector3.up).sqrMagnitude >= 0.01f)
            Learn("move");
        if (Time.unscaledTime >= nextInteractionRefresh)
        {
            nextInteractionRefresh = Time.unscaledTime + 0.5f;
            RefreshInteractionLocks();
        }
        if (Time.unscaledTime < nextRefresh) return;
        nextRefresh = Time.unscaledTime + 0.15f;
        RefreshPhase();
        if (State == null) { QueueControls(); IdleHelp(); return; }
        GardenWaterSupply supply = GardenWaterSupply.Active;
        if (supply != null && supply.Exhausted)
        {
            // The visible game-over panel owns these announcements even if this guide is disabled.
            voice.Clear();
            return;
        }
        if (supply != null && !supply.IsPractice && announcedWaterAttempt != supply.Attempt)
        {
            announcedWaterAttempt = supply.Attempt;
            voice.FinishCurrent();
            int attempt = supply.Attempt;
            // Name the visible sprout before explaining the newly limited water supply.
            if (phase == 1) Say("08_sprout", "phase-1", () => Running && phase == 1);
            foreach (string id in new[] { "water_reserve_intro", "water_reserve_rules" })
                Say(id, id + "-" + attempt, () => Running && supply.Attempt == attempt && State.tomatoPhase < 5);
        }
        if (State.harvested)
        {
            voice.FinishCurrent();
            completed = true;
            ReleaseInteractionLocks();
            Unsubscribe();
            // The closing line is the only request allowed after tutorial completion.
            voice.Enqueue("13_complete", "complete", () => isActiveAndEnabled && State?.harvested == true);
            if (supply != null && supply.HasNoMeasuredWaste)
                voice.Enqueue("water_no_waste_complete", "no-waste", () => isActiveAndEnabled && State?.harvested == true && supply.HasNoMeasuredWaste);
            return;
        }
        if (calendar.IsAdvancing) { voice.FinishCurrent(); return; }
        if (State.waterMillilitres != lastWater)
        {
            lastWater = State.waterMillilitres;
            lastActionAt = Time.unscaledTime;
        }
        bool excess = Excess;
        if (excess && !wasExcess) Help("help_excess_water", () => Excess);
        if (!excess && wasExcess && State.phaseWaterMillilitres > seeds.ExcessLimit(Plant))
            Help("help_drained", () => Caring && !Excess &&
                State.phaseWaterMillilitres > seeds.ExcessLimit(Plant));
        wasExcess = excess;
        if (phase == 0 && Caring && !NeedsWater && !Excess)
            Say("06_enough_water", "enough", () => Caring && phase == 0 && !NeedsWater && !Excess);
        if (phase == 0 && Ready)
            Say("07_first_advance", "advance", () => Ready && phase == 0);
        if (CanEmpty && NeedsWater)
        {
            Help("help_refill", () => CanEmpty && NeedsWater);
            if (supply != null && !supply.IsPractice)
                Say("water_reserve_explanation", "reserve-refill-explanation", () => Caring && CanEmpty && NeedsWater);
        }
        if (supply != null)
        {
            if (supply.IsMissingSoil) Help("help_missed_pot", () => Caring && supply.IsMissingSoil);
            if (!NeedsWater && !Excess && System.Array.Exists(cans, can => can != null && can.IsPouring))
                Help("help_stop_watering", () => Caring && !NeedsWater && !Excess && System.Array.Exists(cans, can => can != null && can.IsPouring));
            if (!supply.IsPractice)
            {
                int attempt = supply.Attempt;
                Say("help_reserve_low", "low-reserve-" + attempt, () => Caring && supply.Attempt == attempt &&
                    supply.ReserveMillilitres > 0.001f && supply.ReserveMillilitres <= supply.InitialReserveMillilitres * 0.25f);
                Say("help_reserve_empty", "empty-reserve-" + attempt, () => Caring && supply.Attempt == attempt &&
                    supply.ReserveMillilitres <= 0.001f && supply.WaterInCansMillilitres > 0.001f);
                int readyPhase = phase;
                if (Ready)
                {
                    Say("water_stopped_success", "stopped-" + phase, () => Ready && phase == readyPhase);
                    Say("water_ready_next_phase", "ready-" + phase, () => Ready && phase == readyPhase);
                }
            }
        }
        QueueControls();
        IdleHelp();
    }

    private void LateUpdate()
    {
        SeedItem target = null;
        if (!GardenMenuController.GardenSuspended && Running && grabInstructionFinished && State == null && !calendar.IsAdvancing)
        {
            foreach (SeedItem seed in seedItems)
            {
                if (seed == null || seed.Crop != SeedCrop.Tomato || seed.IsPlanted ||
                    !seed.isActiveAndEnabled || seed.gameObject.scene != gameObject.scene) continue;
                target = seed;
                break;
            }
        }
        if (target == null || viewer == null)
        {
            if (seedPlantingCaption != null) seedPlantingCaption.gameObject.SetActive(false);
            return;
        }
        if (seedPlantingCaption == null)
        {
            // Keep world scale independent of the seed and the guide's scaled canvas.
            GameObject caption = new("Tomato seed planting instruction");
            caption.layer = 2;
            seedPlantingCaption = caption.AddComponent<TextMesh>();
            seedPlantingCaption.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            MeshRenderer renderer = caption.GetComponent<MeshRenderer>();
            renderer.sharedMaterial = seedPlantingCaption.font.material;
            renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            renderer.receiveShadows = false;
            seedPlantingCaption.anchor = TextAnchor.MiddleCenter;
            seedPlantingCaption.alignment = TextAlignment.Center;
            seedPlantingCaption.characterSize = 0.006f;
            seedPlantingCaption.fontSize = 48;
            seedPlantingCaption.color = Color.white;
        }
        seedPlantingCaption.text = seedPlantingInstruction;
        seedPlantingCaption.transform.position = target.transform.position + Vector3.up * 0.16f;
        Vector3 direction = seedPlantingCaption.transform.position - viewer.position;
        if (direction.sqrMagnitude > 0.0001f)
            seedPlantingCaption.transform.rotation = Quaternion.LookRotation(direction, Vector3.up);
        seedPlantingCaption.gameObject.SetActive(true);
    }

    private void RefreshPhase()
    {
        int currentPhase = State != null ? State.tomatoPhase : -1;
        if (phase == currentPhase) return;
        bool first = phase == -2;
        phase = currentPhase;
        wasExcess = false;
        lastWater = State != null ? State.waterMillilitres : 0f;
        lastActionAt = Time.unscaledTime;
        if (!first) voice.FinishCurrent();
        int captured = phase;
        if (phase < 0)
            Say("03_plant_seed", "plant", () => Running && Step == GuideStep.Plant);
        else if (phase == 0)
        {
            Say("water_practice_intro", "water-practice", () => Caring && phase == 0 && NeedsWater);
        }
        else
        {
            string id = phase switch
            {
                1 => "08_sprout", 2 => "09_young_plant", 3 => "10_flowering",
                4 => "11_green_fruit", _ => "12_harvest"
            };
            Say(id, "phase-" + phase, () => Running && State != null &&
                State.tomatoPhase == captured && !calendar.IsAdvancing);
        }
        QueueControls();
    }

    private void OnAudioFinished(string id)
    {
        if (id == "controls_grab_hands" || id == "controls_grab_controllers")
            grabInstructionFinished = true;
    }

    private void UpdateMode()
    {
        OVRInput.Controller active = OVRInput.GetActiveController();
        GardenInputMode detected = (active & OVRInput.Controller.Hands) != 0 ? GardenInputMode.Hands :
            (active & OVRInput.Controller.Touch) != 0 ? GardenInputMode.Controllers : GardenInputMode.Unknown;
        if (detected != candidateMode) { candidateMode = detected; modeChangedAt = Time.unscaledTime; }
        if (mode == detected || Time.unscaledTime - modeChangedAt < 0.35f) return;
        mode = detected;
        voice.CancelControls();
        demonstration.SetInputMode(mode);
        heldObjects.Clear();
        movementRequested = false;
        movementPracticeStarted = false;
        if (playerOrigin != null) movementStart = playerOrigin.position;
        QueueControls();
    }

    private bool Learned(string control) => learned.Contains(control);
    private void Learn(string control)
    {
        if (GardenMenuController.GardenSuspended) return;
        if (!Running || !learned.Add(control)) return;
        lastActionAt = Time.unscaledTime;
        if (control == "move")
            Say("movement_success", "movement-success", () => Running && State == null);
        RefreshInteractionLocks();
        QueueControls();
    }

    private void QueueControls()
    {
        if (!Running || mode == GardenInputMode.Unknown || calendar.IsAdvancing) return;
        GuideStep step = Step;
        if (step == GuideStep.Move) Control("move", () => Step == GuideStep.Move);
        else if (step == GuideStep.Grab) Control("grab", () => Step == GuideStep.Grab);
        else if (step == GuideStep.Plant)
        {
            Say("03_plant_seed", "plant", () => Running && Step == GuideStep.Plant);
        }
        else if (step == GuideStep.Water && phase == 0)
        {
            if (!Learned("watering_grab")) Control("watering", () => Step == GuideStep.Water && !Learned("watering_grab"));
            else
            {
                Say("04_first_watering", "watering", () => Caring && phase == 0 && NeedsWater);
                Say("05_water_target", "target", () => Caring && phase == 0 && NeedsWater);
            }
        }
        else if (step == GuideStep.Calendar)
        {
            Control("calendar", () => Step == GuideStep.Calendar);
        }
        else if (step == GuideStep.CalendarSelect)
            Control(CanEmpty ? "refill_select" : "calendar_select", () => Step == GuideStep.CalendarSelect);
    }

    private void Control(string name, System.Func<bool> relevant)
    {
        GardenInputMode requestedMode = mode;
        string id = "controls_" + name + (mode == GardenInputMode.Hands ? "_hands" : "_controllers");
        Say(id, id, () => Running && mode == requestedMode && relevant(), false, true);
    }

    private void Say(string id, string key, System.Func<bool> relevant, bool once = true, bool waitForAction = false)
    {
        System.Func<bool> demoRelevant = catalogue.FindTutorialCue(id)?.demo switch
        {
            GardenControlDemo.Water => () => ShowWateringDemonstration,
            GardenControlDemo.Upright => () => System.Array.Exists(cans, can => can != null && can.IsPouring),
            _ => null
        };
        voice.Enqueue(id, key, () => (GardenWaterSupply.Active == null || !GardenWaterSupply.Active.Exhausted) && relevant(), () =>
        {
            // Movement before its own lesson must not skip the demonstration.
            if ((id == "controls_move_hands" || id == "controls_move_controllers") && Step == GuideStep.Move)
            {
                movementPracticeStarted = true;
                movementRequested = false;
                if (playerOrigin != null) movementStart = playerOrigin.position;
            }
            if (catalogue.FindTutorialCue(id).assisted) calendar.RecordTutorialHelp(id);
        }, once, demoRelevant, waitForAction);
    }

    private void Help(string id, System.Func<bool> relevant)
    {
        int capturedPhase = phase;
        Say(id, id + ":" + phase, () => Running && phase == capturedPhase && relevant(), false);
    }

    private void IdleHelp()
    {
        float delay = phase >= 2 ? catalogue.independentHelpSeconds : catalogue.idleHelpSeconds;
        if (Time.unscaledTime - lastActionAt < delay) return;
        lastActionAt = Time.unscaledTime;
        if (Step == GuideStep.Move || Step == GuideStep.Grab || Step == GuideStep.Calendar ||
            Step == GuideStep.CalendarSelect) return;
        if (State == null) Help("help_planting", () => State == null);
        else if (NeedsWater) Help("help_low_water", () => NeedsWater);
        else if (Ready) Help("help_calendar", () => Ready);
    }

    private void OnPlantingRejected(SeedItem seed)
    {
        if (seed != null && seed.Crop == SeedCrop.Tomato)
            Help("help_planting", () => Running && State == null);
    }

    private void OnAdvanceBlocked(string reason)
    {
        if (!Running) return;
        if (Step == GuideStep.Move || Step == GuideStep.Grab) return;
        if (State == null) Help("help_planting", () => State == null);
        else if (Excess) Help("help_excess_water", () => Excess);
        else if (NeedsWater) Help("help_low_water", () => NeedsWater);
    }

    private void OnCalendarVisible(bool visible)
    {
        if (!Running || !visible || (Step != GuideStep.Calendar && Step != GuideStep.CalendarSelect)) return;
        Learn("calendar");
        QueueControls();
    }

    private void OnCalendarAction(GardenTutorialAction action)
    {
        if (Running && (action == GardenTutorialAction.Advance || action == GardenTutorialAction.Refill))
            Learn("calendar_select");
    }

    private void OnMoved(LocomotionEvent evt, Pose delta)
    {
        if (!GardenMenuController.GardenSuspended && Running && movementPracticeStarted && Step == GuideStep.Move &&
            (evt.Translation == LocomotionEvent.TranslationType.Relative ||
             evt.Translation == LocomotionEvent.TranslationType.Velocity) &&
            Vector3.ProjectOnPlane(delta.position, Vector3.up).sqrMagnitude > 0.00000001f)
            movementRequested = true;
    }

    private void ObserveGrabs()
    {
        if (Step != GuideStep.Grab) return;
        foreach (SeedItem seed in seedItems)
        {
            if (seed == null || seed.Crop != SeedCrop.Tomato) continue;
            Grabbable grabbable = seed.GetComponent<Grabbable>();
            ObserveObject(seed.GetInstanceID(), grabbable != null && grabbable.SelectingPointsCount > 0);
        }
        foreach (WateringCan can in cans)
            if (can != null) ObserveObject(can.GetInstanceID(), can.IsHeld);
    }

    private void ObserveObject(int id, bool held)
    {
        if (held) heldObjects.Add(id);
        else if (heldObjects.Remove(id) && Step == GuideStep.Grab) Learn("grab");
    }

    private void RefreshInteractionLocks()
    {
        bool free = !Running || Step == GuideStep.Free;
        if (free) { ReleaseInteractionLocks(); return; }
        GuideStep step = Step;
        foreach (MonoBehaviour behaviour in FindObjectsByType<MonoBehaviour>(FindObjectsInactive.Include, FindObjectsSortMode.None))
        {
            if (behaviour.gameObject.scene != gameObject.scene) continue;
            bool allowed;
            if (behaviour is GrabInteractable || behaviour is HandGrabInteractable)
            {
                Grabbable grab = behaviour.GetComponentInParent<Grabbable>();
                SeedItem seed = grab != null ? grab.GetComponent<SeedItem>() : null;
                WateringCan can = grab != null ? grab.GetComponent<WateringCan>() : null;
                if (seed != null && seed.IsPlanted) { blockedInteractions.Remove(behaviour); continue; }
                allowed = (grab != null && grab.SelectingPointsCount > 0) ||
                    (step != GuideStep.Move && seed != null && seed.Crop == SeedCrop.Tomato) ||
                    (Learned("grab") && State != null && can != null);
            }
            else if (behaviour is LocomotionAxisTurnerInteractor || behaviour is LocomotionTurnerInteractor ||
                behaviour is TeleportInteractor) allowed = false;
            else continue;
            if (allowed)
            {
                if (blockedInteractions.Remove(behaviour)) behaviour.enabled = true;
            }
            else if (behaviour.enabled)
            {
                blockedInteractions.Add(behaviour);
                behaviour.enabled = false;
            }
        }
        if (panel != null) panel.Refresh();
    }

    private void ReleaseInteractionLocks()
    {
        foreach (Behaviour behaviour in blockedInteractions)
        {
            if (behaviour == null) continue;
            SeedItem seed = behaviour.GetComponentInParent<SeedItem>();
            if (seed == null || !seed.IsPlanted) behaviour.enabled = true;
        }
        blockedInteractions.Clear();
        if (panel != null) panel.Refresh();
    }

    private void OnDisable()
    {
        if (active == this) active = null;
        ReleaseInteractionLocks();
        Unsubscribe();
        if (voice != null) { voice.Clear(); voice.enabled = false; }
        if (demonstration != null) demonstration.Hide();
        if (seedPlantingCaption != null) seedPlantingCaption.gameObject.SetActive(false);
    }

    private void OnDestroy()
    {
        if (seedPlantingCaption != null) Destroy(seedPlantingCaption.gameObject);
    }
}

using System;
using System.Collections.Generic;
using UnityEngine;

/// <summary>One voice: finish spoken phrases, discard stale queued help, and preserve urgent resume positions.</summary>
[DisallowMultipleComponent]
public sealed class GronnyVoicePlayer : MonoBehaviour
{
    private sealed class Request
    {
        public GronnyAudioCatalogue.Cue cue;
        public string key;
        public Func<bool> relevant;
        public Func<bool> demonstrationRelevant;
        public Action started;
        public bool waitForAction;
        public bool audioFinished;
        public bool playbackStarted;
        public bool contextExpired;
        public int resumeSample;
        public float visualElapsed;
    }

    public event Action<string> AudioFinished;

    private readonly List<Request> pending = new();
    private readonly HashSet<string> delivered = new();
    private readonly Dictionary<string, float> lastPlayed = new();
    private Request current;
    private AudioSource source;
    private GronnyAudioCatalogue catalogue;
    private GardenControlDemonstration demonstration;
    private float nextVoiceAt;
    private float visualStartedAt;
    private GronnyAudioCatalogue.Cue backgroundDemonstration;
    private Func<bool> backgroundRelevant;
    private float backgroundStartedAt;
    private bool suspended;
    private float suspendedAt;
    private bool menuPlayback;

    public string CurrentCueId => current != null ? current.cue.id : null;

    public void Configure(GronnyAudioCatalogue settings, GardenControlDemonstration visuals, bool menuPlayback = false)
    {
        catalogue = settings;
        demonstration = visuals;
        this.menuPlayback = menuPlayback;
        // A dedicated source keeps tutorial voice independent of ambient audio.
        source = gameObject.AddComponent<AudioSource>();
        source.playOnAwake = false;
        source.loop = false;
        source.spatialBlend = 0f;
        source.dopplerLevel = 0f;
        source.pitch = catalogue.pitch;
        var gestures = FindFirstObjectByType<GardenerMixamoGreeting>();
        if (gestures != null && !menuPlayback) gestures.BindVoiceSource(source);
    }

    public void SetBackgroundDemonstration(string id, Func<bool> relevant)
    {
        backgroundDemonstration = catalogue.Find(id);
        backgroundRelevant = relevant;
    }

    public void Enqueue(string id, string key, Func<bool> relevant, Action started = null, bool once = true,
        Func<bool> demonstrationRelevant = null, bool waitForAction = false)
    {
        GronnyAudioCatalogue.Cue cue = menuPlayback ? catalogue.Find(id) : catalogue.FindTutorialCue(id);
        if (cue == null || cue.clip == null)
        {
            Debug.LogWarning("Gronny audio is missing: " + id, this);
            return;
        }
        if (!isActiveAndEnabled || relevant == null || !relevant() ||
            (once && delivered.Contains(key)) || (current != null && current.key == key) ||
            pending.Exists(request => request.key == key) ||
            (!waitForAction && lastPlayed.TryGetValue(id, out float last) && Time.unscaledTime - last < cue.cooldown)) return;

        var request = new Request { cue = cue, key = key, relevant = relevant, started = started,
            demonstrationRelevant = demonstrationRelevant, waitForAction = waitForAction };
        if (current != null && cue.priority >= 100 && cue.priority > current.cue.priority)
        {
            // Only urgent warnings interrupt. Resume at the sample, never at the first word.
            Request interrupted = current;
            interrupted.resumeSample = interrupted.audioFinished ? 0 : source.timeSamples;
            interrupted.visualElapsed = Time.unscaledTime - visualStartedAt;
            StopCurrent();
            if (!interrupted.contextExpired && interrupted.relevant()) pending.Insert(0, interrupted);
        }
        pending.Add(request);
    }

    public void CancelControls()
    {
        pending.RemoveAll(request => request.cue.mode != GardenInputMode.Unknown);
        if (current != null && current.cue.mode != GardenInputMode.Unknown) ExpireCurrentContext();
    }

    public void FinishCurrent()
    {
        pending.Clear();
        ExpireCurrentContext();
    }

    private void ExpireCurrentContext()
    {
        if (current == null) return;
        current.contextExpired = true;
        current.waitForAction = false;
        demonstration.Hide();
    }

    public void Clear()
    {
        pending.Clear();
        StopCurrent();
    }

    public void SuspendForMenu()
    {
        if (source == null || suspended || menuPlayback) return;
        suspended = true;
        suspendedAt = Time.unscaledTime;
        source.Pause();
        demonstration.Hide();
    }

    private void Update()
    {
        if (source == null) return;
        // Apply on every frame so changing a preference also changes an utterance already playing.
        if (current != null) source.volume = catalogue.voiceVolume * current.cue.volume * GardenPreferences.VoiceVolume;
        if (!menuPlayback && GardenMenuController.GardenSuspended)
        {
            SuspendForMenu();
            return;
        }
        if (suspended)
        {
            float duration = Time.unscaledTime - suspendedAt;
            visualStartedAt += duration;
            backgroundStartedAt += duration;
            nextVoiceAt += duration;
            suspended = false;
            if (current != null && !current.audioFinished) source.UnPause();
        }
        pending.RemoveAll(request => !request.relevant());
        if (current != null)
        {
            if (!current.contextExpired && !current.relevant()) ExpireCurrentContext();
            Request playing = current;
            // Completing an action ends the demo immediately but lets the sentence finish.
            if (!source.isPlaying && !playing.audioFinished)
            {
                playing.audioFinished = true;
                AudioFinished?.Invoke(playing.cue.id);
                if (current != playing) return;
            }
            if (!source.isPlaying && !playing.waitForAction) StopCurrent();
            else
            {
                if (playing.contextExpired) demonstration.Hide();
                else if (playing.cue.demo == GardenControlDemo.None) UpdateBackgroundDemonstration();
                else if (playing.demonstrationRelevant != null && !playing.demonstrationRelevant()) demonstration.Hide();
                else
                {
                    if (!demonstration.IsShowing(playing.cue)) demonstration.Show(playing.cue);
                    if (demonstration.UsesHandTeachingTiming)
                        demonstration.TickTeaching(Mathf.Repeat(Time.unscaledTime - visualStartedAt, demonstration.CycleDurationSeconds));
                    else demonstration.Tick(source.isPlaying ? source.time :
                        Mathf.Repeat(Time.unscaledTime - visualStartedAt, playing.cue.clip.length / catalogue.pitch) * catalogue.pitch);
                }
                return;
            }
        }
        if (Time.unscaledTime < nextVoiceAt || pending.Count == 0)
        {
            UpdateBackgroundDemonstration();
            return;
        }
        int selected = 0;
        for (int i = 1; i < pending.Count; i++)
            if (pending[i].cue.priority > pending[selected].cue.priority) selected = i;
        current = pending[selected];
        pending.RemoveAt(selected);
        if (!current.playbackStarted)
        {
            delivered.Add(current.key);
            lastPlayed[current.cue.id] = Time.unscaledTime;
        }
        source.clip = current.cue.clip;
        source.volume = catalogue.voiceVolume * current.cue.volume * GardenPreferences.VoiceVolume;
        source.pitch = catalogue.pitch;
        if (!current.audioFinished)
        {
            source.Play();
            if (current.resumeSample > 0) source.timeSamples = Mathf.Min(current.resumeSample, current.cue.clip.samples - 1);
        }
        visualStartedAt = Time.unscaledTime - current.visualElapsed;
        if (current.cue.demo == GardenControlDemo.None) UpdateBackgroundDemonstration();
        else if (current.demonstrationRelevant == null || current.demonstrationRelevant()) demonstration.Show(current.cue);
        current.playbackStarted = true;
        Action onStarted = current.started;
        current.started = null;
        onStarted?.Invoke();
    }

    private void UpdateBackgroundDemonstration()
    {
        if (backgroundDemonstration == null || backgroundDemonstration.clip == null ||
            backgroundRelevant == null || !backgroundRelevant())
        {
            demonstration.Hide();
            return;
        }
        // Continue the visual while later spoken instructions play, without replaying its audio.
        if (!demonstration.IsShowing(backgroundDemonstration))
        {
            demonstration.Show(backgroundDemonstration);
            backgroundStartedAt = Time.unscaledTime;
        }
        float duration = Mathf.Max(0.01f, backgroundDemonstration.clip.length / catalogue.pitch);
        demonstration.Tick(Mathf.Repeat(Time.unscaledTime - backgroundStartedAt, duration) * catalogue.pitch);
    }

    private void StopCurrent()
    {
        if (source != null) source.Stop();
        if (demonstration != null) demonstration.Hide();
        current = null;
        nextVoiceAt = Time.unscaledTime + (catalogue != null ? catalogue.gapSeconds : 0f);
    }

    private void OnDisable() => Clear();
}

using UnityEngine;
using UnityEngine.Rendering;

/// <summary>Standalone Meta visuals with configurable pose/press timing; no tracked hands or interactors.</summary>
[DisallowMultipleComponent]
public sealed class GardenControlDemonstration : MonoBehaviour
{
    private GronnyAudioCatalogue catalogue;
    private Transform gardeningAnchor;
    private GardenInputMode mode;
    private GameObject anchor;
    private GameObject model;
    private Transform motion;
    private Transform animationRoot;
    private Transform[] joints;
    private Quaternion[][] poses;
    private Vector3[] restPositions;
    private TextMesh caption;
    private LineRenderer pointer;
    private Material visualMaterial;
    private GronnyAudioCatalogue.Cue cue;
    private AnimationClip pressClip;
    private GameObject buttonHighlight;
    private bool fixedGardeningPosition;
    private AnimationClip thumbSwipeClip;
    private Transform[] thumbJoints;
    private Quaternion[] thumbBaseRotations;
    private float[] handStepTimes;

    public bool UsesHandTeachingTiming => handStepTimes != null;
    public float CycleDurationSeconds => handStepTimes != null
        ? Mathf.Max(cue.clip.length / catalogue.pitch, handStepTimes[handStepTimes.Length - 1] + catalogue.handPoseHoldSeconds)
        : cue != null ? cue.clip.length / catalogue.pitch : 0f;

    public bool IsShowing(GronnyAudioCatalogue.Cue instruction) => anchor != null && cue == instruction;

    public void Configure(GronnyAudioCatalogue settings, Transform gardeningAnchor = null)
    {
        catalogue = settings;
        this.gardeningAnchor = gardeningAnchor;
    }

    public void SetInputMode(GardenInputMode inputMode)
    {
        mode = inputMode;
        // A mode change cancels any demonstration, including a general watering instruction.
        Hide();
    }

    public void Show(GronnyAudioCatalogue.Cue instruction)
    {
        Hide();
        if (instruction.demo == GardenControlDemo.None || mode == GardenInputMode.Unknown) return;
        Transform viewer = Camera.main != null ? Camera.main.transform : null;
        if (viewer == null)
        {
            GameObject eye = GameObject.Find("CenterEyeAnchor");
            if (eye != null) viewer = eye.transform;
        }
        if (viewer == null) return;
        cue = instruction;
        if (mode == GardenInputMode.Hands && cue.mode == GardenInputMode.Hands && cue.steps != null && cue.steps.Length > 0)
        {
            // Keep short replacement WAVs from compressing each teaching pose into a flash.
            handStepTimes = new float[cue.steps.Length];
            for (int i = 1; i < handStepTimes.Length; i++)
                handStepTimes[i] = Mathf.Max(cue.steps[i].at / catalogue.pitch,
                    handStepTimes[i - 1] + catalogue.handPoseHoldSeconds);
        }
        bool left = cue.demo == GardenControlDemo.Calendar || cue.demo == GardenControlDemo.Move ||
            (mode == GardenInputMode.Hands && cue.demo == GardenControlDemo.CalendarSelect);
        if (cue.rightHand) left = false;
        var hand = left ? catalogue.leftHand : catalogue.rightHand;
        GameObject prefab = mode == GardenInputMode.Hands ? hand.prefab :
            left ? catalogue.leftController : catalogue.rightController;
        if (prefab == null) { Hide(); return; }

        anchor = new GameObject("Gronny control demonstration");
        anchor.SetActive(false);
        fixedGardeningPosition = gardeningAnchor != null && cue.demo != GardenControlDemo.Move;
        if (fixedGardeningPosition)
        {
            // Use the scene's clear demonstration area, independent of the player's pose or watering.
            anchor.transform.SetPositionAndRotation(gardeningAnchor.position, gardeningAnchor.rotation);
            anchor.transform.localScale = Vector3.one * 1.5f;
        }
        else
        {
            // Preserve the existing movement instruction placement and hand angle.
            Vector3 forward = Vector3.ProjectOnPlane(viewer.forward, Vector3.up).normalized;
            if (forward.sqrMagnitude < 0.01f) forward = Vector3.forward;
            Quaternion facing = Quaternion.LookRotation(forward, Vector3.up);
            Vector3 offset = catalogue.viewOffset;
            if (left) offset.x = -Mathf.Abs(offset.x);
            Vector3 position = viewer.position + facing * offset;
            if (mode == GardenInputMode.Hands &&
                (cue.demo == GardenControlDemo.Move || cue.demo == GardenControlDemo.Calendar))
                facing = Quaternion.LookRotation(position - viewer.position, Vector3.up);
            anchor.transform.SetPositionAndRotation(position, facing);
        }
        GameObject moving = new("Motion");
        motion = moving.transform;
        motion.SetParent(anchor.transform, false);
        model = Instantiate(prefab, motion);
        model.transform.localPosition = Vector3.zero;
        model.transform.localRotation = Quaternion.Euler(mode == GardenInputMode.Hands
            ? catalogue.handEulerAngles : catalogue.controllerEulerAngles);
        if (cue.rightHand && mode == GardenInputMode.Hands)
            model.transform.localRotation = MirrorRotation(model.transform.localRotation);
        // Imported FBX roots include the centimetres-to-metres conversion.
        model.transform.localScale = prefab.transform.localScale * catalogue.visualScale;
        foreach (MonoBehaviour behaviour in model.GetComponentsInChildren<MonoBehaviour>(true))
            behaviour.enabled = false;
        foreach (Animator animator in model.GetComponentsInChildren<Animator>(true)) animator.enabled = false;
        foreach (Collider collider in model.GetComponentsInChildren<Collider>(true)) collider.enabled = false;
        foreach (Rigidbody body in model.GetComponentsInChildren<Rigidbody>(true))
        { body.isKinematic = true; body.detectCollisions = false; }
        foreach (Transform child in model.GetComponentsInChildren<Transform>(true)) child.gameObject.layer = 2;

        if (visualMaterial == null)
        {
            visualMaterial = new Material(catalogue.demonstrationMaterial);
            visualMaterial.SetColor("_BaseColor", new Color(0.4f, 0.85f, 0.9f, 1f));
        }
        foreach (Renderer renderer in model.GetComponentsInChildren<Renderer>(true))
        {
            // Keep Meta's ghost wire material and the controller's readable button colours.
            renderer.shadowCastingMode = ShadowCastingMode.Off;
            renderer.receiveShadows = false;
        }
        if (mode == GardenInputMode.Hands)
        {
            animationRoot = model.transform.Find(hand.animationRoot);
            if (animationRoot == null)
            {
                Debug.LogWarning("Gronny hand animation root is missing: " + hand.animationRoot, this);
                Hide();
                return;
            }
            CachePoses(hand);
            thumbSwipeClip = hand.thumbSwipe;
            if (cue.demo == GardenControlDemo.Move && thumbSwipeClip != null) PrepareThumbSwipe();
        }
        else
        {
            animationRoot = model.transform;
            pressClip = cue.controllerAnimation != null ? cue.controllerAnimation : cue.demo switch
            {
                GardenControlDemo.Move => catalogue.controllerStick,
                GardenControlDemo.Grab or GardenControlDemo.WateringGrab => catalogue.controllerGrip,
                GardenControlDemo.Calendar => catalogue.controllerY,
                GardenControlDemo.CalendarSelect => catalogue.controllerTrigger,
                _ => null
            };
            Transform target = string.IsNullOrEmpty(cue.controllerTarget) ? null : model.transform.Find(cue.controllerTarget);
            if (target != null)
                buttonHighlight = MakeSymbol(PrimitiveType.Sphere, "Example pressed control", target,
                    Vector3.zero, Vector3.one * 0.8f);
        }
        GameObject text = new("Step caption");
        text.transform.SetParent(anchor.transform, false);
        text.transform.localPosition = new Vector3(0f, -0.20f, 0f);
        caption = text.AddComponent<TextMesh>();
        caption.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
        caption.GetComponent<MeshRenderer>().sharedMaterial = caption.font.material;
        caption.anchor = TextAnchor.MiddleCenter;
        caption.alignment = TextAlignment.Center;
        caption.characterSize = 0.008f;
        caption.fontSize = fixedGardeningPosition ? 64 : 48;
        caption.color = Color.white;
        if (cue.demo == GardenControlDemo.CalendarSelect) CreatePointer();
        if (cue.demo == GardenControlDemo.Water || cue.demo == GardenControlDemo.Upright || cue.demo == GardenControlDemo.WateringGrab) CreateCanSymbol();
        foreach (Transform child in anchor.GetComponentsInChildren<Transform>(true)) child.gameObject.layer = 2;
        anchor.SetActive(true);
        Tick(0f);
        GardenPresentationPlacement placement = anchor.AddComponent<GardenPresentationPlacement>();
        placement.Configure(anchor.transform, viewer, keepStatic: fixedGardeningPosition);
    }

    private void CachePoses(GronnyAudioCatalogue.HandVisual hand)
    {
        joints = animationRoot.GetComponentsInChildren<Transform>(true);
        poses = new Quaternion[5][];
        restPositions = new Vector3[joints.Length];
        poses[0] = new Quaternion[joints.Length];
        for (int j = 0; j < joints.Length; j++)
        {
            poses[0][j] = joints[j].localRotation;
            restPositions[j] = joints[j].localPosition;
        }
        AnimationClip[] clips = { null, hand.pinch, hand.curled, hand.point, hand.thumbFree };
        for (int p = 1; p < poses.Length; p++)
        {
            for (int j = 0; j < joints.Length; j++) joints[j].localRotation = poses[0][j];
            if (clips[p] != null) clips[p].SampleAnimation(animationRoot.gameObject, 0f);
            poses[p] = new Quaternion[joints.Length];
            for (int j = 0; j < joints.Length; j++) poses[p][j] = joints[j].localRotation;
        }
        if (cue.demo == GardenControlDemo.Move)
        {
            // Meta's mid-fist pose opens the fingers; the activation tap only moves the thumb.
            for (int j = 0; j < joints.Length; j++)
                if (!joints[j].name.Contains("_thumb"))
                    poses[(int)GardenDemoPose.Curled][j] = poses[(int)GardenDemoPose.ThumbFree][j];
        }
    }

    public void Tick(float audioSeconds) => TickAt(audioSeconds, false);

    public void TickTeaching(float elapsedSeconds) => TickAt(elapsedSeconds, UsesHandTeachingTiming);

    private void TickAt(float audioSeconds, bool handClock)
    {
        if (anchor == null || cue == null || cue.steps == null || cue.steps.Length == 0) return;
        int index = 0;
        for (int i = 1; i < cue.steps.Length; i++)
            if (audioSeconds >= StepTime(i, handClock)) index = i;
        GronnyAudioCatalogue.Step step = cue.steps[index];
        GronnyAudioCatalogue.Step previous = index > 0 ? cue.steps[index - 1] : step;
        float blend = handClock ? Mathf.Max(catalogue.blendSeconds, catalogue.handPoseBlendSeconds) : catalogue.blendSeconds;
        float t = Mathf.SmoothStep(0f, 1f, Mathf.Clamp01((audioSeconds - StepTime(index, handClock)) / blend));
        motion.localPosition = Vector3.Lerp(previous.position, step.position, t);
        motion.localRotation = Quaternion.Slerp(Quaternion.Euler(previous.rotation), Quaternion.Euler(step.rotation), t);
        if (cue.rightHand)
        {
            Vector3 position = motion.localPosition;
            position.x = -position.x;
            motion.localPosition = position;
            motion.localRotation = MirrorRotation(motion.localRotation);
        }
        if (mode == GardenInputMode.Hands && cue.demo == GardenControlDemo.Calendar)
            caption.text = "Pinch with your " + (cue.rightHand ? "right" : "left") + " hand\nto open and close\nthe calendar.";
        else
            caption.text = fixedGardeningPosition ? ReadableCaption(step.label) : step.label;
        if (mode == GardenInputMode.Hands && poses != null)
        {
            for (int j = 0; j < joints.Length; j++)
            {
                joints[j].localPosition = restPositions[j];
                joints[j].localRotation = Quaternion.Slerp(poses[(int)previous.pose][j], poses[(int)step.pose][j], t);
            }
            // The swipe direction is a timed, configurable thumb rotation, independent of frame rate.
            if (cue.demo == GardenControlDemo.Move && step.pose == GardenDemoPose.ThumbFree)
                foreach (Transform joint in joints)
                    if (joint.name.EndsWith("thumb1"))
                        joint.localRotation *= Quaternion.Euler(Vector3.Lerp(previous.thumbRotation, step.thumbRotation, t));
            ApplyThumbSwipe(index, audioSeconds, handClock);
        }
        else if (pressClip != null)
        {
            float pressed = Mathf.Lerp(previous.press, step.press, t);
            pressClip.SampleAnimation(animationRoot.gameObject, pressed * pressClip.length);
        }
        if (pointer != null)
        {
            pointer.SetPosition(0, motion.localPosition);
            pointer.SetPosition(1, motion.localPosition + Vector3.forward * 0.35f);
        }
        if (buttonHighlight != null) buttonHighlight.SetActive(step.press > 0f);
    }

    private static Quaternion MirrorRotation(Quaternion rotation) =>
        new(rotation.x, -rotation.y, -rotation.z, rotation.w);

    private float StepTime(int index, bool handClock) => handClock ? handStepTimes[index] : cue.steps[index].at;

    private void PrepareThumbSwipe()
    {
        var animatedThumb = new System.Collections.Generic.List<Transform>();
        foreach (Transform joint in joints)
        {
            if (joint.name.StartsWith("b_") && joint.name.Contains("_thumb")) animatedThumb.Add(joint);
        }
        thumbJoints = animatedThumb.ToArray();
        thumbBaseRotations = new Quaternion[thumbJoints.Length];
    }

    private void ApplyThumbSwipe(int index, float audioSeconds, bool handClock)
    {
        if (cue.demo != GardenControlDemo.Move || thumbSwipeClip == null || thumbJoints == null) return;
        GronnyAudioCatalogue.Step from = cue.steps[index];
        GronnyAudioCatalogue.Step to = index + 1 < cue.steps.Length ? cue.steps[index + 1] : from;
        // Interpolate across the entire authored swipe interval, not just blendSeconds
        // after the next pose. This keeps the visible stroke under its spoken instruction.
        float fromTime = StepTime(index, handClock);
        float toTime = StepTime(Mathf.Min(index + 1, cue.steps.Length - 1), handClock);
        float progress = toTime > fromTime ? Mathf.SmoothStep(0f, 1f,
            Mathf.InverseLerp(fromTime, toTime, audioSeconds)) : 1f;
        float weight = Mathf.Lerp(from.thumbSwipeWeight, to.thumbSwipeWeight, progress);
        if (weight > 0f)
        {
            for (int j = 0; j < thumbJoints.Length; j++) thumbBaseRotations[j] = thumbJoints[j].localRotation;
            thumbSwipeClip.SampleAnimation(animationRoot.gameObject,
                Mathf.Lerp(from.thumbSwipeProgress, to.thumbSwipeProgress, progress) * thumbSwipeClip.length);
            for (int j = 0; j < thumbJoints.Length; j++)
                thumbJoints[j].localRotation = Quaternion.Slerp(thumbBaseRotations[j], thumbJoints[j].localRotation, weight);
        }
    }

    private static string ReadableCaption(string text)
    {
        if (string.IsNullOrEmpty(text) || text.Length <= 26 || text.Contains("\n")) return text;
        int split = text.LastIndexOf(' ', 26);
        return split > 0 ? text.Substring(0, split) + "\n" + text.Substring(split + 1) : text;
    }

    private void CreatePointer()
    {
        GameObject ray = new("Example selection ray");
        ray.transform.SetParent(anchor.transform, false);
        pointer = ray.AddComponent<LineRenderer>();
        pointer.useWorldSpace = false;
        pointer.positionCount = 2;
        pointer.startWidth = pointer.endWidth = 0.003f;
        pointer.sharedMaterial = visualMaterial;
        GameObject button = MakeSymbol(PrimitiveType.Cube, "Example button", anchor.transform,
            new Vector3(0f, 0f, 0.35f), new Vector3(0.13f, 0.07f, 0.01f));
        button.transform.localRotation = Quaternion.identity;
    }

    private void CreateCanSymbol()
    {
        MakeSymbol(PrimitiveType.Cylinder, "Example can body", motion,
            new Vector3(0.07f, -0.03f, 0.03f), new Vector3(0.08f, 0.05f, 0.08f));
        GameObject spout = MakeSymbol(PrimitiveType.Cube, "Example spout", motion,
            new Vector3(0.13f, 0f, 0.03f), new Vector3(0.09f, 0.02f, 0.02f));
        spout.transform.localRotation = Quaternion.Euler(0f, 0f, 25f);
    }

    private GameObject MakeSymbol(PrimitiveType primitive, string name, Transform parent, Vector3 position, Vector3 scale)
    {
        GameObject symbol = GameObject.CreatePrimitive(primitive);
        symbol.name = name;
        symbol.layer = 2;
        symbol.transform.SetParent(parent, false);
        symbol.transform.localPosition = position;
        symbol.transform.localScale = scale;
        Collider collider = symbol.GetComponent<Collider>();
        collider.enabled = false;
        Destroy(collider);
        Renderer renderer = symbol.GetComponent<Renderer>();
        renderer.sharedMaterial = visualMaterial;
        renderer.shadowCastingMode = ShadowCastingMode.Off;
        return symbol;
    }

    public void Hide()
    {
        if (anchor != null) { anchor.SetActive(false); Destroy(anchor); }
        anchor = null;
        model = null;
        cue = null;
        pointer = null;
        pressClip = null;
        buttonHighlight = null;
        poses = null;
        joints = null;
        fixedGardeningPosition = false;
        thumbSwipeClip = null;
        thumbJoints = null;
        thumbBaseRotations = null;
        handStepTimes = null;
    }

    private void OnDisable() => Hide();
    private void OnDestroy()
    {
        Hide();
        if (visualMaterial != null) Destroy(visualMaterial);
    }
}

using Oculus.Interaction;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.SceneManagement;
using UnityEngine.UI;

/// <summary>Session menu, installed before the garden's Start methods without changing the saved scene.</summary>
[DisallowMultipleComponent, DefaultExecutionOrder(-200)]
public sealed class GardenMenuController : MonoBehaviour
{
    private static GardenMenuController active;
    private static bool restartAtPlanting;
    private static bool reloading;
    private bool startAtPlanting;
    private bool startOnReady;
    private GardenMenuView menu;
    private GardenMenuView launcher;
    private GardenMenuView gameOver;
    private bool gameOverVisible;
    private int gameOverAttempt;
    private float nextGameOverPlacement;
    [SerializeField, Min(0f), Tooltip("Space above the fixed gardening guide, in metres.")]
    private float guidePanelGap = 0.08f;
    [SerializeField, Tooltip("Launch menu position relative to the player's initial floor origin, in metres.")]
    private Vector3 launchOffset = new Vector3(0f, 1.45f, 1.3f);
    private GardenInteractionSuspension suspension;
    private Transform viewer;
    private bool visible;
    private bool started;
    private bool awaitingRelease;
    private bool menuInputArmed;
    private float releasedAt = float.NaN;
    private float menuReleasedAt = float.NaN;
    private bool placed;
    private Text launcherHint;
    private GronnyAudioCatalogue audioCatalogue;
    private GronnyVoicePlayer menuVoice;
    private GardenControlDemonstration menuDemonstration;
    private GardenInputMode controlsMode = GardenInputMode.Hands;
    private enum Page { Home, Controls, Demonstration, Sound, GameOver }
    private Page page;
    private string previewId;
    private bool controlsIntroPlayed;

    public static bool HasStarted => active == null || active.started;
    public static bool StartsAtPlanting => active != null && active.startAtPlanting;
    public static bool GardenSuspended => active != null && (active.visible || active.awaitingRelease);

    public static bool RayHitsMenu(Ray ray, float distance)
    {
        if (active == null) return false;
        GardenMenuView target = active.gameOverVisible ? active.gameOver : active.visible ? active.menu : active.launcher;
        return target != null && target.Root.activeInHierarchy && target.Collider.enabled &&
            target.Collider.Raycast(ray, out _, distance);
    }

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    private static void ResetStatics() { active = null; restartAtPlanting = false; reloading = false; }

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    private static void Register()
    {
        SceneManager.sceneLoaded -= OnSceneLoaded;
        SceneManager.sceneLoaded += OnSceneLoaded;
    }

    private static void OnSceneLoaded(Scene scene, LoadSceneMode mode)
    {
        if (scene.name != "Garden_Moves") return;
        reloading = false;
        if (FindFirstObjectByType<GardenMenuController>() != null) return;
        new GameObject("Garden menu and preferences").AddComponent<GardenMenuController>();
    }

    private void Awake()
    {
        active = this;
        startAtPlanting = restartAtPlanting;
        startOnReady = startAtPlanting;
        restartAtPlanting = false;
        GardenPreferences.Load();
        if (FindFirstObjectByType<GardenWaterSupply>() == null) gameObject.AddComponent<GardenWaterSupply>();
        suspension = new GardenInteractionSuspension(gameObject.scene);
        menu = new GardenMenuView("Garden menu", transform, new Vector2(860f, 710f));
        launcher = new GardenMenuView("Open garden menu", transform, new Vector2(360f, 155f));
        gameOver = new GardenMenuView("Water game over", transform, new Vector2(860f, 610f));
        launcher.Clear();
        launcher.Button("Menu", new Vector2(0f, 25f), new Vector2(320f, 75f), Open);
        launcherHint = launcher.Label("Point + pinch / Trigger", new Vector2(0f, -45f), new Vector2(340f, 50f), 22);
        if (FindFirstObjectByType<PointableCanvasModule>() == null)
        {
            EventSystem events = FindFirstObjectByType<EventSystem>();
            if (events == null) events = new GameObject("Garden menu events", typeof(EventSystem)).GetComponent<EventSystem>();
            events.gameObject.AddComponent<PointableCanvasModule>();
        }
        visible = true;
        ResetMenuInput();
        InitializeAudio();
        ShowHome();
        menu.Root.SetActive(true);
        suspension.Tick();
    }

    private void InitializeAudio()
    {
        audioCatalogue = Resources.Load<GronnyAudioCatalogue>("GronnyAudio/Tutorial");
        if (audioCatalogue == null)
        {
            Debug.LogWarning("Garden menu audio catalogue is missing.", this);
            return;
        }
        menuDemonstration = gameObject.AddComponent<GardenControlDemonstration>();
        menuDemonstration.Configure(audioCatalogue);
        menuVoice = gameObject.AddComponent<GronnyVoicePlayer>();
        menuVoice.Configure(audioCatalogue, menuDemonstration, menuPlayback: true);
    }

    private void Update()
    {
        if (viewer == null)
        {
            OVRCameraRig rig = FindFirstObjectByType<OVRCameraRig>();
            viewer = rig != null ? rig.centerEyeAnchor : Camera.main != null ? Camera.main.transform : null;
            if (viewer != null)
            {
                if (!placed)
                {
                    PlaceLaunchStation(rig != null ? rig.transform : viewer);
                    placed = true;
                }
                menu.SetViewer(viewer);
                launcher.SetViewer(viewer);
                gameOver.SetViewer(viewer);
            }
        }
        if (startOnReady && placed)
        {
            startOnReady = false;
            menuInputArmed = true;
            Continue();
        }
        GardenWaterSupply supply = GardenWaterSupply.Active;
        if (started && supply != null && supply.Exhausted && gameOverAttempt != supply.Attempt)
            ShowGameOver(supply);
        if (gameOverVisible && viewer != null && Time.unscaledTime >= nextGameOverPlacement)
        {
            nextGameOverPlacement = Time.unscaledTime + 0.5f;
            Vector3 direction = (gameOver.Root.transform.position - viewer.position).normalized;
            if (!gameOver.Root.GetComponent<Canvas>().enabled || Vector3.Dot(viewer.forward, direction) < 0.25f)
                PlaceGameOver();
        }
        if (GardenSuspended)
        {
            suspension.Tick();
            bool released = suspension.InputsReleased();
            HandleInputRelease(released, Time.unscaledTime);
        }
    }

    // Keep the release decision independent of the device sample so it can be verified
    // with deterministic samples without pretending to simulate tracked hands or controllers.
    private void HandleInputRelease(bool released, float now)
    {
        if (visible)
        {
            if (!released) menuReleasedAt = float.NaN;
            else if (float.IsNaN(menuReleasedAt)) menuReleasedAt = now;
            if (!menuInputArmed && !float.IsNaN(menuReleasedAt) && now - menuReleasedAt >= 0.15f)
            {
                menuInputArmed = true;
                menu.SetInputEnabled(true);
                if (gameOverVisible) gameOver.SetInputEnabled(true);
            }
        }
        if (!awaitingRelease) return;
        if (!released) releasedAt = float.NaN;
        else if (float.IsNaN(releasedAt)) releasedAt = now;
        if (float.IsNaN(releasedAt) || now - releasedAt < 0.2f) return;
        awaitingRelease = false;
        suspension.Release();
        launcherHint.text = "Point + pinch / Trigger";
    }

    private void LateUpdate()
    {
        // Catch props released by Meta later in the frame without forcing held objects out of the hand.
        if (GardenSuspended) suspension.Tick();
    }

    public void Open()
    {
        if (visible) return;
        GardenWaterSupply.Active?.EvaluateExhaustion();
        visible = true;
        awaitingRelease = false;
        ResetMenuInput();
        FindFirstObjectByType<CalendarVisibilityController>()?.HideForMenu();
        foreach (GronnyVoicePlayer voice in FindObjectsByType<GronnyVoicePlayer>(FindObjectsSortMode.None)) voice.SuspendForMenu();
        suspension.Tick();
        foreach (WateringCan can in FindObjectsByType<WateringCan>(FindObjectsSortMode.None)) can.SuspendPouring();
        launcher.Root.SetActive(false);
        ShowHome();
        menu.Root.SetActive(true);
    }

    private void Continue()
    {
        if (!menuInputArmed || (gameOverVisible && GardenWaterSupply.Active != null && GardenWaterSupply.Active.Exhausted)) return;
        StopMenuAudio();
        gameOverVisible = false;
        gameOver.Root.SetActive(false);
        bool firstLaunch = !started;
        started = true;
        visible = false;
        awaitingRelease = true;
        releasedAt = float.NaN;
        menu.Root.SetActive(false);
        if (firstLaunch) PlacePauseStation();
        launcher.Root.SetActive(true);
        launcherHint.text = "Release selection.\nStraighten your free index finger.";
    }

    private void ResetMenuInput()
    {
        menuInputArmed = false;
        menuReleasedAt = float.NaN;
        menu.SetInputEnabled(false);
        gameOver.SetInputEnabled(false);
    }

    public static bool RestartAtPlanting(Scene scene)
    {
        if (reloading) return false;
        if (!Application.CanStreamedLevelBeLoaded(scene.path))
        {
            Debug.LogError("Add Garden_Moves to Build Settings to enable retrying.");
            return false;
        }
        reloading = true;
        restartAtPlanting = true;
        // Reload the scene so crop state, props, water and spoken-cue history
        // all belong to a new session. Only the planting entry point crosses the load.
        foreach (GronnyVoicePlayer voice in FindObjectsByType<GronnyVoicePlayer>(FindObjectsSortMode.None)) voice.Clear();
        try
        {
            if (SceneManager.LoadSceneAsync(scene.path, LoadSceneMode.Single) != null) return true;
        }
        catch (System.Exception error)
        {
            Debug.LogException(error);
        }
        restartAtPlanting = false;
        reloading = false;
        return false;
    }

    private void ShowGameOver(GardenWaterSupply supply)
    {
        if (!visible) Open();
        StopMenuAudio();
        gameOverAttempt = supply.Attempt;
        gameOverVisible = true;
        page = Page.GameOver;
        ResetMenuInput();
        menu.Root.SetActive(false);
        launcher.Root.SetActive(false);
        gameOver.Clear();
        gameOver.Label("Game over", new Vector2(0f, 225f), new Vector2(790f, 75f), 46);
        gameOver.Label(supply.FailureMessage,
            new Vector2(0f, 120f), new Vector2(790f, 100f), 29);
        gameOver.Label(supply.SummaryText, new Vector2(0f, 10f), new Vector2(790f, 80f), 27);
        gameOver.Label("Start again by planting a new seed.\nGronny will guide you from the planting step.",
            new Vector2(0f, -90f), new Vector2(790f, 90f), 25);
        gameOver.Button("Try again", new Vector2(0f, -215f), new Vector2(650f, 85f), () =>
        {
            if (menuInputArmed) supply.Retry();
        });
        gameOver.Root.SetActive(true);
        PlaceGameOver();
        // The empty-supply recording only describes literal exhaustion. For an
        // insufficient remainder, the visible explanation accompanies the retry cue.
        if (supply.AvailableMillilitres <= 0.001f)
            menuVoice?.Enqueue("water_supply_exhausted", "game-over-" + supply.Attempt, () => gameOverVisible && supply.Exhausted);
        menuVoice?.Enqueue("water_retry", "game-over-retry-" + supply.Attempt, () => gameOverVisible && supply.Exhausted);
    }

    private void PlaceGameOver()
    {
        if (viewer == null) return;
        Vector3 forward = Vector3.ProjectOnPlane(viewer.forward, Vector3.up).normalized;
        if (forward.sqrMagnitude < 0.01f) forward = Vector3.forward;
        gameOver.Root.transform.SetPositionAndRotation(viewer.position + forward * 1.2f - Vector3.up * 0.05f,
            Quaternion.LookRotation(forward, Vector3.up));
        var placement = gameOver.Root.GetComponent<GardenPresentationPlacement>() ?? gameOver.Root.AddComponent<GardenPresentationPlacement>();
        placement.Configure(gameOver.Root.transform, viewer, gameOver.Collider, checkFullSightline: true);
    }

    private void ShowHome()
    {
        StopMenuAudio();
        page = Page.Home;
        menu.Clear();
        menu.Label(started ? "Garden paused" : "Cozy Garden", new Vector2(0f, 275f), new Vector2(790f, 65f), 42);
        menu.Label("Point at a button, then pinch or press Trigger.", new Vector2(0f, 200f), new Vector2(790f, 70f));
        bool retry = started && GardenWaterSupply.Active != null && GardenWaterSupply.Active.Exhausted;
        menu.Button(retry ? "Try again" : started ? "Return to garden" : "Play", new Vector2(0f, 95f), new Vector2(650f, 85f), () =>
        {
            if (!menuInputArmed) return;
            if (retry) { GardenWaterSupply.Active.Retry(); return; }
            Continue();
        });
        menu.Button("Controls", new Vector2(0f, -15f), new Vector2(650f, 85f), ShowControls);
        menu.Button("Sound settings", new Vector2(0f, -125f), new Vector2(650f, 85f), ShowSound);
        menu.Label(started
            ? "Adjust sound or review the controls.\nYour current garden continues when you return."
            : "Practise first with free refills.\nThen grow your tomato with a limited water reserve.\nRefilling uses that reserve: save water to finish.",
            new Vector2(0f, -260f), new Vector2(790f, 110f), 25);
    }

    private void ShowControls()
    {
        StopMenuAudio();
        page = Page.Controls;
        menu.Clear();
        menu.Label("Controls", new Vector2(0f, 280f), new Vector2(790f, 65f), 38);
        menu.Button(controlsMode == GardenInputMode.Hands ? "Hands — selected" : "Hands",
            new Vector2(-185f, 200f), new Vector2(340f, 65f), () => { controlsMode = GardenInputMode.Hands; ShowControls(); });
        menu.Button(controlsMode == GardenInputMode.Controllers ? "Controllers — selected" : "Controllers",
            new Vector2(185f, 200f), new Vector2(340f, 65f), () => { controlsMode = GardenInputMode.Controllers; ShowControls(); });
        menu.Label("Choose a demonstration to watch and hear.\nThe garden stays paused while you review.",
            new Vector2(0f, 125f), new Vector2(790f, 70f), 25);
        menu.Button("Movement", new Vector2(-185f, 25f), new Vector2(340f, 65f), () => ShowDemonstration("move"));
        menu.Button("Grab and release", new Vector2(185f, 25f), new Vector2(340f, 65f), () => ShowDemonstration("grab"));
        menu.Button("Open and close calendar", new Vector2(-185f, -75f), new Vector2(340f, 65f), () => ShowDemonstration("calendar"));
        menu.Button("Select buttons", new Vector2(185f, -75f), new Vector2(340f, 65f), () => ShowDemonstration("calendar_select"));
        menu.Button("Watering can", new Vector2(-185f, -175f), new Vector2(340f, 65f), () => ShowDemonstration("watering"));
        menu.Button("Refill water", new Vector2(185f, -175f), new Vector2(340f, 65f), () => ShowDemonstration("refill_select"));
        menu.Button("Back", new Vector2(0f, -290f), new Vector2(710f, 65f), ShowHome);
        if (!controlsIntroPlayed && menuVoice != null)
        {
            controlsIntroPlayed = true;
            menuVoice.Enqueue("menu_tutorial_intro", "controls-intro", () => visible && page == Page.Controls);
        }
    }

    private void ShowDemonstration(string control, bool right = false)
    {
        StopMenuAudio();
        page = Page.Demonstration;
        string id = "controls_" + control + (controlsMode == GardenInputMode.Hands ? "_hands" : "_controllers");
        bool hasSides = control == "move" || control == "calendar";
        if (hasSides && right) id += "_right";
        GronnyAudioCatalogue.Cue cue = audioCatalogue != null ? audioCatalogue.Find(id) : null;
        previewId = id;
        menu.Clear();
        menu.Label(control switch { "move" => "Movement", "grab" => "Grab and release",
            "calendar" => "Calendar", "watering" => "Watering can", "refill_select" => "Refill water",
            _ => "Select buttons" }, new Vector2(0f, 280f), new Vector2(790f, 65f), 38);
        string description = controlsMode == GardenInputMode.Hands ? "Hand tracking" : "Touch controllers";
        if (hasSides) description += right
            ? " — right-hand preview\nLive movement and calendar still use the left side."
            : " — left side\nMatches the current movement and calendar controls.";
        menu.Label(description, new Vector2(0f, 195f), new Vector2(790f, 95f), 24);
        menu.Label(cue != null && !string.IsNullOrEmpty(cue.transcript) ? cue.transcript
            : "Watch the demonstration.\nYou can replay it or stop it at any time.",
            new Vector2(0f, 30f), new Vector2(760f, 225f), 26);
        menu.Button("Replay", new Vector2(-185f, -125f), new Vector2(340f, 65f), () => PlayDemonstration(id));
        menu.Button("Stop", new Vector2(185f, -125f), new Vector2(340f, 65f), StopMenuAudio);
        if (hasSides)
            menu.Button(right ? "Preview left hand" : "Preview right hand", new Vector2(0f, -205f),
                new Vector2(710f, 65f), () => ShowDemonstration(control, !right));
        menu.Button("Back", new Vector2(0f, -290f), new Vector2(710f, 65f), ShowControls);
        PlayDemonstration(id);
    }

    private void PlayDemonstration(string id)
    {
        StopMenuAudio();
        previewId = id;
        if (menuVoice == null) return;
        menuDemonstration.SetInputMode(controlsMode);
        menuVoice.Enqueue(id, "preview-" + id, () => visible && page == Page.Demonstration && previewId == id,
            once: false, waitForAction: true);
    }

    private void StopMenuAudio()
    {
        previewId = null;
        menuVoice?.Clear();
    }

    private void ShowSound()
    {
        if (page != Page.Sound) StopMenuAudio();
        page = Page.Sound;
        menu.Clear();
        menu.Label("Sound settings", new Vector2(0f, 285f), new Vector2(790f, 65f), 38);
        VolumeRow("Overall", GardenPreferences.MasterVolume, 185f, GardenPreferences.SetMasterVolume);
        VolumeRow("Gronny", GardenPreferences.VoiceVolume, 85f, GardenPreferences.SetVoiceVolume);
        menu.Button(GardenPreferences.Muted ? "Sound: muted — select to unmute" : "Mute sound", new Vector2(0f, -15f),
            new Vector2(710f, 65f), () => { GardenPreferences.SetMuted(!GardenPreferences.Muted); ShowSound(); });
        menu.Button("Test voice", new Vector2(-185f, -105f), new Vector2(340f, 65f), () =>
        {
            StopMenuAudio();
            menuVoice?.Enqueue("settings_voice_sample", "voice-sample", () => visible && page == Page.Sound, once: false);
        });
        menu.Button("Stop voice", new Vector2(185f, -105f), new Vector2(340f, 65f), StopMenuAudio);
        menu.Button("Restore sound defaults", new Vector2(0f, -195f), new Vector2(710f, 75f),
            () => { GardenPreferences.RestoreSoundDefaults(); ShowSound(); });
        menu.Button("Back", new Vector2(0f, -290f), new Vector2(710f, 65f), ShowHome);
    }

    private void VolumeRow(string title, float value, float y, System.Action<float> change)
    {
        menu.Label(title + ": " + Mathf.RoundToInt(value * 100f) + "%", new Vector2(0f, y), new Vector2(460f, 75f), 30);
        menu.Button("−", new Vector2(-300f, y), new Vector2(110f, 80f), () => { change(value - 0.1f); ShowSound(); });
        menu.Button("+", new Vector2(300f, y), new Vector2(110f, 80f), () => { change(value + 0.1f); ShowSound(); });
    }

    private void PlaceLaunchStation(Transform playerOrigin)
    {
        // Snapshot the spawn origin once so the launch screen stays where the player enters.
        Vector3 forward = Vector3.ProjectOnPlane(playerOrigin.forward, Vector3.up).normalized;
        if (forward.sqrMagnitude < 0.01f) forward = Vector3.forward;
        Quaternion rotation = Quaternion.LookRotation(forward, Vector3.up);
        transform.SetPositionAndRotation(playerOrigin.position + rotation * launchOffset, rotation);
    }

    private void PlacePauseStation()
    {
        TomatoPrototypeGuide guide = FindFirstObjectByType<TomatoPrototypeGuide>();
        RectTransform panel = guide != null ? guide.GetComponent<RectTransform>() : null;
        if (panel != null)
        {
            Vector3 top = panel.TransformPoint(new Vector3(panel.rect.center.x, panel.rect.yMax, 0f));
            // Snapshot the authored pose once so tracking and later rig motion cannot move the UI.
            transform.SetPositionAndRotation(top + panel.up * guidePanelGap, panel.rotation);
            menu.Root.transform.localPosition = Vector3.up * (menu.Collider.size.y * menu.Root.transform.localScale.y * 0.5f);
            launcher.Root.transform.localPosition = Vector3.up * (launcher.Collider.size.y * launcher.Root.transform.localScale.y * 0.5f);
            GardenWaterTankDisplay tank = FindFirstObjectByType<GardenWaterTankDisplay>();
            if (tank != null)
            {
                Pose aboveGuide = new(launcher.Root.transform.position, launcher.Root.transform.rotation);
                launcher.Root.transform.SetPositionAndRotation(tank.transform.position, tank.transform.rotation);
                tank.transform.SetPositionAndRotation(aboveGuide.position, aboveGuide.rotation);
            }
            return;
        }
        // A scene without the guide keeps a usable pause menu at the original launch station.
    }

    private void OnDestroy()
    {
        StopMenuAudio();
        suspension?.Release();
        if (active == this) active = null;
    }
}

using UnityEngine;
using UnityEngine.UI;

/// <summary>Short visual coaching; measured water feedback lives above each planted tomato.</summary>
[DisallowMultipleComponent]
public sealed class TomatoPrototypeGuide : MonoBehaviour
{
    [SerializeField] private SeedsController seeds;
    [Header("Editable scene panel")]
    [SerializeField] private Text instruction;
    [Tooltip("Secondary instructions on Gronny's panel. Water measurements appear above the plant.")]
    [SerializeField] private Text water;
    [SerializeField, Tooltip("Fixed scene position for gardening demonstrations beside Gronny. Movement keeps its existing placement.")]
    private Transform gardeningDemonstrationAnchor;
    [SerializeField, Tooltip("Keep the board visible at its authored scene position, independent of tracking and watering.")]
    private bool keepPanelStatic = true;
    [SerializeField] private bool facePlayer = true;
    [SerializeField] private bool followPlantedPot;
    [SerializeField] private Vector3 potPanelOffset = new(0.25f, 0.46f, 0f);
    [SerializeField, TextArea] private string welcomeInstruction = "Pick up the red tomato seed.\nDrop it onto the soil in an empty small pot.";
    [SerializeField, TextArea] private string initialWaterInformation = "One seed per pot.\nGrab: pinch or press Grip.\nCalendar: left-hand pinch away from objects, or Y.";
    [SerializeField, Min(5f)] private float idleHintSeconds = 25f;
    private Color neutralWaterColor;
    private CalendarSystem calendar;
    private Transform viewer;
    private string message;
    private float messageUntil;
    private float lastActionAt;
    private float lastTotalWater;
    private int lastPhase = -1;
    private bool successShown;
    private float nextRefresh;
    private GronnyTutorial audioTutorial;

    public Transform GardeningDemonstrationAnchor => gardeningDemonstrationAnchor;

    private void Start()
    {
        GardenRoundedPanel.ApplyToHierarchy(transform);
        if (instruction == null || water == null)
        {
            Debug.LogError("Assign both scene text labels to the tomato guide.", this);
            enabled = false;
            return;
        }
        if (seeds == null) seeds = FindFirstObjectByType<SeedsController>();
        if (seeds == null || seeds.Calendar == null) { enabled = false; return; }
        neutralWaterColor = water.color;
        calendar = seeds.Calendar;
        seeds.Guidance += Say;
        calendar.AdvanceBlocked += OnAdvanceBlocked;
        if (gameObject.scene.name == "Garden_Moves")
            audioTutorial = GetComponent<GronnyTutorial>() ?? gameObject.AddComponent<GronnyTutorial>();
        GameObject eye = GameObject.Find("CenterEyeAnchor");
        viewer = eye != null ? eye.transform : Camera.main != null ? Camera.main.transform : null;
        GardenPresentationPlacement placement = gameObject.AddComponent<GardenPresentationPlacement>();
        placement.Configure(transform, viewer, keepStatic: keepPanelStatic);
        Say(welcomeInstruction);
    }

    public void Say(string text)
    {
        message = text;
        messageUntil = Time.unscaledTime + 6f;
        lastActionAt = Time.unscaledTime;
    }

    private void OnAdvanceBlocked(string reason)
    {
        // The calendar may include a numeric deficit; keep measurements at the plant.
        Say(reason != null && reason.StartsWith("Still needs ")
            ? "Check the water bar above your plant.\nWater the soil before advancing." : reason);
    }

    private void LateUpdate()
    {
        SeedsController.PlantedSeed plant = seeds.PrototypeTomato;
        if (!keepPanelStatic && followPlantedPot && plant != null && plant.pot != null)
            transform.position = plant.pot.PlantingPoint + potPanelOffset;
        if (viewer == null && Camera.main != null) viewer = Camera.main.transform;
        if (!keepPanelStatic && facePlayer && viewer != null)
        {
            Vector3 direction = transform.position - viewer.position;
            direction.y = 0f;
            if (direction.sqrMagnitude > 0.01f) transform.rotation = Quaternion.LookRotation(direction);
        }
        if (Time.unscaledTime < nextRefresh) return;
        nextRefresh = Time.unscaledTime + 0.25f;
        Refresh(plant);
    }

    private void Refresh(SeedsController.PlantedSeed plant)
    {
        if (GardenMenuController.GardenSuspended)
        {
            if (GardenWaterSupply.Active != null && GardenWaterSupply.Active.Exhausted)
            {
                instruction.text = "Game over: not enough water to finish.";
                water.text = "Select Try again on the panel in front of you.\nStart again by planting a new seed with Gronny.";
                return;
            }
            instruction.text = GardenMenuController.HasStarted ? "Garden menu is open." : "Welcome to Cozy Garden.";
            water.text = GardenMenuController.HasStarted
                ? "Adjust sound or review the controls above.\nSelect Return to garden when ready."
                : "The launch menu is at the garden entrance.\nSelect Play when ready.";
            return;
        }
        if (calendar.IsAdvancing)
        {
            water.color = neutralWaterColor;
            instruction.text = "Watch your tomato grow.";
            water.text = "Time is passing.\nWatering is paused.";
            return;
        }
        if (plant == null)
        {
            water.color = neutralWaterColor;
            string step = null;
            string detail = null;
            bool guided = audioTutorial != null && audioTutorial.TryGetInstruction(out step, out detail);
            instruction.text = guided ? step : message;
            water.text = guided ? detail : initialWaterInformation;
            return;
        }
        CalendarSystem.PlantSave saved = seeds.GetState(plant);
        if (saved == null) return;
        GardenWaterSupply supply = GardenWaterSupply.Active;
        if (supply != null && supply.Exhausted)
        {
            instruction.text = "Game over: not enough water to finish.\nYour tomato still needs water.";
            water.text = "Calendar: select Try again.\nStart again by planting a new seed with Gronny.";
            return;
        }
        if (saved.harvested && supply != null)
        {
            instruction.text = "Well done! You grew and harvested a tomato.";
            water.text = supply.SummaryText;
            return;
        }
        if (saved.waterMillilitres != lastTotalWater || saved.tomatoPhase != lastPhase)
        {
            // A planting or blocked-advance hint must not ask for more water after watering succeeds.
            if (saved.waterMillilitres != lastTotalWater) messageUntil = 0f;
            lastActionAt = Time.unscaledTime;
            lastTotalWater = saved.waterMillilitres;
            lastPhase = saved.tomatoPhase;
        }
        if (saved.harvested && !successShown)
        {
            successShown = true;
            Say("Well done! You harvested a tomato.\nCalendar: Restart to play again.");
        }
        bool excess = saved.retainedWaterMillilitres > seeds.ExcessLimit(plant) && saved.tomatoPhase < 5;
        bool pouring = Time.unscaledTime - saved.lastWaterAt < 0.5f;
        string prompt = saved.harvested ? "Well done! You harvested a tomato.\nCalendar: Restart to play again." :
            saved.tomatoPhase >= 5 ? "Pick the largest red tomato.\nPlace it in the harvest tray." :
            excess ? "Stop watering.\nLet the extra water drain away." :
            saved.retainedWaterMillilitres >= seeds.TargetMillilitres(plant)
                ? "Enough water! Hold the can upright.\nCalendar: Advance phase."
                : saved.tomatoPhase == 4
                    ? "You're in charge.\nCheck what your plant needs."
                    : "Water the soil near the roots.\nKeep the water off the leaves.";
        if (!pouring && Time.unscaledTime < messageUntil && !excess) prompt = message;
        if (!pouring && Time.unscaledTime - lastActionAt > idleHintSeconds && !saved.harvested)
            prompt += "\nCalendar: left-hand pinch away from objects, or Y.";
        water.color = neutralWaterColor;
        if (audioTutorial != null && audioTutorial.TryGetInstruction(out string currentStep, out string control))
        {
            instruction.text = currentStep;
            water.text = control;
            return;
        }
        instruction.text = prompt;
        water.text = saved.harvested ? "Calendar: Restart to play again."
            : saved.tomatoPhase >= 5 ? "Place the red tomato in the harvest tray."
            : "Check the water bar above your plant.\nCalendar: left-hand pinch away from objects, or Y.";
    }

    private void OnDestroy()
    {
        if (seeds != null) seeds.Guidance -= Say;
        if (calendar != null) calendar.AdvanceBlocked -= OnAdvanceBlocked;
    }

    private void OnEnable()
    {
        if (audioTutorial != null) audioTutorial.enabled = true;
    }

    private void OnDisable()
    {
        if (audioTutorial != null) audioTutorial.enabled = false;
    }
}

using System;
