/// <summary>Creates the initial catalogue once; later Inspector timing edits are preserved.</summary>
public static class GronnyAudioSetup
{
    private const string CataloguePath = "Assets/Resources/GronnyAudio/Tutorial.asset";
    private const string Interaction = "Packages/com.meta.xr.sdk.interaction";
    private const string Core = "Packages/com.meta.xr.sdk.core";

    [MenuItem("Garden/Gronny/Create initial audio catalogue")]
    public static void CreateInitialCatalogue()
    {
        if (AssetDatabase.LoadAssetAtPath<GronnyAudioCatalogue>(CataloguePath) != null)
        {
            Debug.Log("Gronny catalogue already exists. Inspector edits have been preserved.");
            return;
        }
        Directory.CreateDirectory("Assets/Resources/GronnyAudio");
        AssetDatabase.Refresh();
        var catalogue = ScriptableObject.CreateInstance<GronnyAudioCatalogue>();
        var cues = new List<GronnyAudioCatalogue.Cue>();
        string[] ids = {
            "01_welcome", "02_tomato_intro", "03_plant_seed", "04_first_watering", "05_water_target",
            "06_enough_water", "07_first_advance", "08_sprout", "09_young_plant", "10_flowering",
            "11_green_fruit", "12_harvest", "13_complete", "help_planting", "help_low_water",
            "help_excess_water", "help_drained", "help_calendar", "help_refill"
        };
        foreach (string id in ids)
        {
            var cue = MakeCue(id, "Assets/Audio/dialogues_cozy_gardening", GardenInputMode.Unknown);
            if (id == "04_first_watering")
            {
                cue.demo = GardenControlDemo.Water;
                cue.steps = new[] { Step(0, GardenDemoPose.Open, "Pick up the watering can"),
                    Step(2.6f, GardenDemoPose.Pinch, "Hold the can"),
                    Step(4.6f, GardenDemoPose.Pinch, "Tilt over the soil", rotation: new Vector3(0, 0, -65)),
                    Step(7.0f, GardenDemoPose.Pinch, "Aim near the roots", rotation: new Vector3(0, 0, -65)) };
            }
            if (id == "06_enough_water" || id == "help_excess_water")
            {
                cue.demo = GardenControlDemo.Upright;
                cue.steps = new[] { Step(0, GardenDemoPose.Pinch, "Stop pouring", rotation: new Vector3(0, 0, -65)),
                    Step(1.2f, GardenDemoPose.Pinch, "Hold the can upright") };
                cue.priority = id == "help_excess_water" ? 100 : 50;
            }
            if (id == "help_refill") cue.priority = 20;
            cues.Add(cue);
        }
        foreach (GardenInputMode mode in new[] { GardenInputMode.Hands, GardenInputMode.Controllers })
        {
            string suffix = mode == GardenInputMode.Hands ? "hands" : "controllers";
            foreach (string control in new[] { "move", "grab", "calendar", "calendar_select" })
            {
                var cue = MakeCue("controls_" + control + "_" + suffix, "Assets/Audio/controls_", mode);
                cue.demo = control switch { "move" => GardenControlDemo.Move, "grab" => GardenControlDemo.Grab,
                    "calendar" => GardenControlDemo.Calendar, _ => GardenControlDemo.CalendarSelect };
                cue.steps = ControlSteps(control, mode);
                cues.Add(cue);
            }
        }
        catalogue.cues = cues.ToArray();
        catalogue.leftHand = Hand("Left", "l");
        catalogue.rightHand = Hand("Right", "r");
        string left = Core + "/Meshes/MetaQuestTouchPlus/MetaQuestTouchPlus_Left.fbx";
        string right = Core + "/Meshes/MetaQuestTouchPlus/MetaQuestTouchPlus_Right.fbx";
        catalogue.leftController = Require<GameObject>(left);
        catalogue.rightController = Require<GameObject>(right);
        catalogue.controllerStick = Clip(left, "left_touchplus_controller_stickN");
        catalogue.controllerY = Clip(left, "left_touchplus_controller_button02");
        catalogue.controllerGrip = Clip(right, "right_quest_touch_plus_controller_grip");
        catalogue.controllerTrigger = Clip(right, "right_quest_touch_plus_controller_trigger");
        ConfigureControllerTargets(catalogue);
        Shader shader = Shader.Find("Universal Render Pipeline/Unlit");
        if (shader == null) throw new InvalidOperationException("The installed URP Unlit shader is missing.");
        var material = new Material(shader) { name = "Gronny demonstration" };
        material.SetColor("_BaseColor", new Color(0.4f, 0.85f, 0.9f, 1f));
        AssetDatabase.CreateAsset(material, "Assets/Resources/GronnyAudio/Demonstration.mat");
        catalogue.demonstrationMaterial = material;
        GronnyWaterSavingAudioSetup.Apply(catalogue);
        GronnyMenuAudioSetup.AddCues(catalogue);
        AssetDatabase.CreateAsset(catalogue, CataloguePath);
        AssetDatabase.SaveAssets();
        WriteInventory(catalogue);
        Debug.Log("Gronny: connected all " + catalogue.cues.Length + " audio files.");
    }

    private static GronnyAudioCatalogue.Cue MakeCue(string id, string folder, GardenInputMode mode)
    {
        string[] matches = Directory.GetFiles(folder, "*", SearchOption.AllDirectories)
            .Where(file => Path.GetFileNameWithoutExtension(file) == id && Path.GetExtension(file) != ".meta")
            .ToArray();
        if (matches.Length != 1) throw new InvalidOperationException(id + ": expected one audio file; found " + matches.Length);
        return new GronnyAudioCatalogue.Cue { id = id, clip = Require<AudioClip>(matches[0].Replace('\\', '/')),
            mode = mode, assisted = id.StartsWith("help_") || id.StartsWith("controls_") ||
                id == "03_plant_seed" || id == "04_first_watering" || id == "05_water_target" ||
                id == "06_enough_water" || id == "07_first_advance" || id == "08_sprout" || id == "12_harvest",
            cooldown = id == "help_excess_water" ? 8f : id.StartsWith("help_") ? 35f : 0f };
    }

    private static GronnyAudioCatalogue.HandVisual Hand(string side, string suffix)
    {
        string animations = Interaction + "/Runtime/Animations/Hands/";
        return new GronnyAudioCatalogue.HandVisual {
            prefab = Require<GameObject>(Interaction + "/Runtime/Prefabs/HandGrab/Ghost-Hand" + side + ".prefab"),
            animationRoot = "OculusHand_" + suffix.ToUpperInvariant(),
            pinch = Require<AnimationClip>(animations + "HandPinch_" + suffix + "_.anim"),
            curled = Require<AnimationClip>(animations + "HandMidFist_" + suffix + "_.anim"),
            point = Require<AnimationClip>(animations + "IndexPoint_" + suffix + "_.anim"),
            thumbFree = Require<AnimationClip>(animations + "ThumbUp_" + suffix + "_.anim"),
            thumbSwipe = Require<AnimationClip>("Assets/Resources/GronnyAudio/ThumbSwipe" + side + ".anim") };
    }

    private static AnimationClip Clip(string path, string name) =>
        AssetDatabase.LoadAllAssetsAtPath(path).OfType<AnimationClip>().FirstOrDefault(clip => clip.name == name)
        ?? throw new InvalidOperationException("Meta controller animation is missing: " + name);

    public static void ConfigureControllerTargets(GronnyAudioCatalogue catalogue)
    {
        foreach (var cue in catalogue.cues.Where(cue => cue.mode == GardenInputMode.Controllers))
        {
            AnimationClip clip = cue.controllerAnimation != null ? cue.controllerAnimation : cue.demo switch {
                GardenControlDemo.Move => catalogue.controllerStick,
                GardenControlDemo.Grab or GardenControlDemo.WateringGrab => catalogue.controllerGrip,
                GardenControlDemo.Calendar => catalogue.controllerY,
                _ => catalogue.controllerTrigger };
            cue.controllerTarget = AnimationUtility.GetCurveBindings(clip).First().path;
        }
    }

    private static T Require<T>(string path) where T : UnityEngine.Object =>
        AssetDatabase.LoadAssetAtPath<T>(path) ?? throw new InvalidOperationException("Missing asset: " + path);

    private static GronnyAudioCatalogue.Step Step(float at, GardenDemoPose pose, string label,
        Vector3 position = default, Vector3 rotation = default, float press = 0f, Vector3 thumbRotation = default,
        float thumbSwipeProgress = 0f, float thumbSwipeWeight = 0f) =>
        new() { at = at, pose = pose, label = label, position = position, rotation = rotation, press = press,
            thumbRotation = thumbRotation, thumbSwipeProgress = thumbSwipeProgress, thumbSwipeWeight = thumbSwipeWeight };

    public static void ConfigureHandMovement(GronnyAudioCatalogue catalogue) =>
        catalogue.Find("controls_move_hands").steps = ControlSteps("move", GardenInputMode.Hands);

    private static GronnyAudioCatalogue.Step[] ControlSteps(string control, GardenInputMode mode)
    {
        bool hands = mode == GardenInputMode.Hands;
        // Show the thumb side of the fist with the thumb upright, rather than the back of the hand.
        Vector3 movementRotation = new(2.74f, 262.35f, 143.91f);
        // Show more of the upright left hand's back so the gesture is easier to imitate.
        Vector3 calendarRotation = new(0f, 155f, 180f);
        // The left index points forward at the example button, with the back of the hand facing up.
        Vector3 calendarSelectionRotation = new(-105f, 0f, 0f);
        return control switch {
            "move" when hands => new[] {
                Step(0, GardenDemoPose.ThumbFree, "Curl the index; keep the thumb free", rotation: movementRotation),
                Step(3.2f, GardenDemoPose.Curled, "Tap the index with the thumb", rotation: movementRotation),
                Step(4.5f, GardenDemoPose.ThumbFree, "Movement active", rotation: movementRotation),
                Step(5.8f, GardenDemoPose.ThumbFree, "Swipe forward to step", rotation: movementRotation, thumbSwipeWeight: 1f),
                Step(7.0f, GardenDemoPose.ThumbFree, "Swipe forward to step", rotation: movementRotation, thumbSwipeProgress: 1f, thumbSwipeWeight: 1f),
                Step(8.3f, GardenDemoPose.ThumbFree, "Swipe back to step back", rotation: movementRotation, thumbSwipeProgress: 1f, thumbSwipeWeight: 1f),
                Step(9.5f, GardenDemoPose.ThumbFree, "Swipe back to step back", rotation: movementRotation, thumbSwipeWeight: 1f),
                Step(10.5f, GardenDemoPose.Point, "Straighten the index to exit", rotation: movementRotation) },
            "move" => new[] { Step(0, GardenDemoPose.Open, "Move the joystick", press: 1),
                Step(3f, GardenDemoPose.Open, "Release to stop") },
            "grab" => new[] {
                Step(0, GardenDemoPose.Open, "Move close to the object"),
                Step(2.3f, GardenDemoPose.Pinch, hands ? "Pinch and hold" : "Hold the grip button", press: 1),
                Step(4.2f, GardenDemoPose.Pinch, "Keep holding while moving", new Vector3(0.08f, 0.05f, 0), press: 1),
                Step(6.5f, GardenDemoPose.Open, "Release to let go", new Vector3(0.08f, 0.05f, 0)) },
            "calendar" when hands => new[] {
                Step(0, GardenDemoPose.Open, "Left hand away from objects", new Vector3(-0.08f, 0, 0), calendarRotation),
                Step(3.4f, GardenDemoPose.Pinch, "Pinch", new Vector3(-0.08f, 0, 0), calendarRotation),
                Step(6f, GardenDemoPose.Open, "Release", new Vector3(-0.08f, 0, 0), calendarRotation) },
            "calendar" => new[] { Step(0, GardenDemoPose.Open, "Left controller: Y"),
                Step(1.2f, GardenDemoPose.Open, "Press Y", press: 1), Step(3f, GardenDemoPose.Open, "Release Y") },
            "calendar_select" when hands => new[] {
                Step(0, GardenDemoPose.Point, "Point at the button", rotation: calendarSelectionRotation),
                Step(2.5f, GardenDemoPose.Pinch, "Pinch", rotation: calendarSelectionRotation, press: 1),
                Step(5f, GardenDemoPose.Point, "Release to select", rotation: calendarSelectionRotation) },
            _ => new[] { Step(0, GardenDemoPose.Point, hands ? "Point at the button" : "Point the controller"),
                Step(2.5f, GardenDemoPose.Pinch, hands ? "Pinch" : "Press the index trigger", press: 1),
                Step(5f, GardenDemoPose.Point, "Release to select") }
        };
    }

    internal static void WriteInventory(GronnyAudioCatalogue catalogue)
    {
        Directory.CreateDirectory("Docs");
        var report = new StringBuilder("# Inventario de audio de Gronny\n\n");
        report.AppendLine("Archivo original | Duración (s) | Modo | Demostración | SHA-256\n---|---:|---|---|---");
        using var sha = SHA256.Create();
        foreach (var cue in catalogue.cues)
        {
            string path = AssetDatabase.GetAssetPath(cue.clip);
            string hash = BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(path))).Replace("-", "");
            report.AppendLine($"`{path}` | {cue.clip.length:0.00} | {cue.mode} | {cue.demo} | `{hash}`");
        }
        File.WriteAllText("Docs/GronnyAudioInventory.md", report.ToString());
    }
}

using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;

/// <summary>Adds the recorded menu cues without replacing existing Inspector edits or audio assets.</summary>
public static class GronnyMenuAudioSetup
{
    private const string CataloguePath = "Assets/Resources/GronnyAudio/Tutorial.asset";
    private const string Controller = "Packages/com.meta.xr.sdk.core/Meshes/MetaQuestTouchPlus/MetaQuestTouchPlus_Right.fbx";

    [Serializable] private sealed class Entry { public string id = ""; public string text = ""; }
    [Serializable] private sealed class Script { public Entry[] entries = Array.Empty<Entry>(); }

    [MenuItem("Garden/Gronny/Connect menu and accessibility audio")]
    public static void Connect()
    {
        var catalogue = AssetDatabase.LoadAssetAtPath<GronnyAudioCatalogue>(CataloguePath);
        if (catalogue == null) throw new InvalidOperationException("Create the original Gronny catalogue first.");
        AddCues(catalogue);
        EditorUtility.SetDirty(catalogue);
        AssetDatabase.SaveAssetIfDirty(catalogue);
    }

    public static void AddCues(GronnyAudioCatalogue catalogue)
    {
        string json = File.ReadAllText("Docs/GronnyMenuYAccesibilidad.json");
        Entry[] entries = JsonUtility.FromJson<Script>("{\"entries\":" + json + "}").entries;
        var cues = catalogue.cues.ToList();
        foreach (Entry entry in entries)
        {
            if (catalogue.Find(entry.id) != null) continue;
            string baseId = entry.id.EndsWith("_accessible") ? entry.id[..^11]
                : entry.id.EndsWith("_left") ? entry.id[..^5]
                : entry.id.EndsWith("_right") ? entry.id[..^6] : null;
            GronnyAudioCatalogue.Cue template = baseId != null ? catalogue.Find(baseId) : null;
            if (baseId != null && template == null)
                throw new InvalidOperationException("Missing original cue: " + baseId);
            var cue = template != null
                ? JsonUtility.FromJson<GronnyAudioCatalogue.Cue>(JsonUtility.ToJson(template))
                : new GronnyAudioCatalogue.Cue { cooldown = 0f };
            cue.id = entry.id;
            cue.transcript = entry.text;
            cue.clip = AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/menu_accessibility/" + entry.id + ".wav");
            if (cue.clip == null) throw new InvalidOperationException("Missing recorded audio: " + entry.id);
            cue.rightHand = entry.id.EndsWith("_right");
            if (template?.clip != null && template.clip.length > 0f)
                foreach (var step in cue.steps) step.at *= cue.clip.length / template.clip.length;
            if (cue.rightHand && cue.mode == GardenInputMode.Hands)
                foreach (var step in cue.steps) step.label = step.label?.Replace("Left", "Right").Replace("left", "right");
            if (cue.rightHand && cue.mode == GardenInputMode.Controllers)
            {
                bool movement = cue.demo == GardenControlDemo.Move;
                string animation = "right_quest_touch_plus_controller_" + (movement ? "stickN" : "button02");
                cue.controllerAnimation = AssetDatabase.LoadAllAssetsAtPath(Controller)
                    .OfType<AnimationClip>().Single(clip => clip.name == animation);
                cue.controllerTarget = AnimationUtility.GetCurveBindings(cue.controllerAnimation)
                    .First(binding => !string.IsNullOrEmpty(binding.path)).path;
                if (!movement)
                    foreach (var step in cue.steps) step.label = step.label?.Replace("Left", "Right").Replace("Y", "B");
            }
            cues.Add(cue);
        }
        catalogue.cues = cues.ToArray();
    }
}

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEngine;

/// <summary>Connects the supplied water-saving lesson without changing Meta assets.</summary>
public static class GronnyWaterSavingAudioSetup
{
    [Serializable] private sealed class Line { public string id = ""; public string text = ""; }
    [Serializable] private sealed class Script { public Line[] entries = Array.Empty<Line>(); }
    [Serializable] private sealed class Import
    {
        public FileRecord[] files = Array.Empty<FileRecord>();
        public string welcome_sha256 = "";
    }
    [Serializable] private sealed class FileRecord
    {
        public string id = "";
        public string backup = "";
        public string source_sha256 = "";
        public string override_sha256 = "";
        public string previous_revision_backup = "";
    }

    [MenuItem("Garden/Gronny/Connect water-saving lesson")]
    public static void Connect()
    {
        var catalogue = AssetDatabase.LoadAssetAtPath<GronnyAudioCatalogue>("Assets/Resources/GronnyAudio/Tutorial.asset");
        if (catalogue == null) throw new InvalidOperationException("The existing Gronny catalogue is missing.");
        Apply(catalogue);
        EditorUtility.SetDirty(catalogue);
        AssetDatabase.SaveAssetIfDirty(catalogue);
        GronnyAudioSetup.WriteInventory(catalogue);
    }

    public static void Apply(GronnyAudioCatalogue catalogue)
    {
        const string scriptPath = "Docs/GronnyWaterSavingDialogues.json";
        if (!File.Exists(scriptPath)) return;
        var script = JsonUtility.FromJson<Script>("{\"entries\":" + File.ReadAllText(scriptPath) + "}");
        var import = JsonUtility.FromJson<Import>(File.ReadAllText("Docs/WaterSavingAudioImport.json"));
        var cues = catalogue.cues.ToList();
        bool retime = catalogue.waterSavingAudioVersion == 0;
        // Update original cues first: new watering/refill demonstrations clone their timings.
        foreach (Line line in script.entries.Where(line => catalogue.Find(line.id) != null))
        {
            var cue = catalogue.Find(line.id);
            var clip = LoadClip(line.id);
            FileRecord record = import.files.First(file => file.id == line.id);
            bool retimeSeed = catalogue.waterSavingAudioVersion < 2 && !string.IsNullOrEmpty(record.override_sha256);
            bool retimeMovement = catalogue.waterSavingAudioVersion < 3 &&
                (line.id == "controls_move_hands" || line.id == "controls_move_controllers") &&
                !string.IsNullOrEmpty(record.override_sha256);
            if (retime || retimeSeed || retimeMovement)
            {
                string backup = retime ? record.backup : record.previous_revision_backup;
                if (!File.Exists(backup))
                    backup = Path.Combine("Docs/AudioBackups", Path.GetFileName(Path.GetDirectoryName(backup)), Path.GetFileName(backup));
                float oldDuration = ReadWaveDuration(backup);
                foreach (var step in cue.steps) step.at *= clip.length / oldDuration;
            }
            cue.clip = clip;
            cue.transcript = line.text;
        }
        foreach (Line line in script.entries.Where(line => catalogue.Find(line.id) == null))
        {
            GronnyAudioCatalogue.Cue cue;
            if (line.id.StartsWith("controls_watering_") || line.id.StartsWith("controls_refill_select_"))
            {
                bool hands = line.id.EndsWith("_hands");
                bool watering = line.id.StartsWith("controls_watering_");
                var template = catalogue.Find("controls_" + (watering ? "grab" : "calendar_select") + (hands ? "_hands" : "_controllers"));
                cue = JsonUtility.FromJson<GronnyAudioCatalogue.Cue>(JsonUtility.ToJson(template));
                var clip = LoadClip(line.id);
                foreach (var step in cue.steps) step.at *= clip.length / template.clip.length;
                if (watering)
                {
                    cue.demo = GardenControlDemo.WateringGrab;
                    cue.steps = new[]
                    {
                        Step(0f, GardenDemoPose.Open, hands ? "Move your open hand close" : "Move the controller close"),
                        Step(clip.length * 0.3f, GardenDemoPose.Curled, hands ? "Close your fingers around the can" : "Hold Grip", 1f),
                        Step(clip.length * 0.7f, GardenDemoPose.Curled, hands ? "Keep your fingers closed" : "Keep holding Grip", 1f)
                    };
                }
            }
            else cue = new GronnyAudioCatalogue.Cue { cooldown = line.id.StartsWith("help_") ? 12f : 0f };
            cue.id = line.id;
            cue.clip = LoadClip(line.id);
            cue.transcript = line.text;
            cue.assisted = line.id.StartsWith("help_") || line.id.StartsWith("controls_");
            cue.priority = line.id == "water_supply_exhausted" ? 100 : line.id.StartsWith("help_") ? 20 : 0;
            cues.Add(cue);
        }
        catalogue.cues = cues.ToArray();
        if (retime)
        {
            // The replacement first-watering recording starts at tilting, after the separate grip cue.
            var watering = catalogue.Find("04_first_watering");
            watering.steps = new[]
            {
                new GronnyAudioCatalogue.Step { at = 0f, pose = GardenDemoPose.Curled,
                    rotation = new Vector3(0f, 0f, -65f), label = "Tilt over the soil, near the roots" },
                Step(watering.clip.length * 0.6f, GardenDemoPose.Curled, "Turn upright to stop pouring")
            };
        }
        catalogue.waterSavingAudioVersion = Mathf.Max(catalogue.waterSavingAudioVersion,
            import.files.Any(file => file.id == "controls_move_hands" && !string.IsNullOrEmpty(file.override_sha256)) ? 3 :
            import.files.Any(file => !string.IsNullOrEmpty(file.override_sha256)) ? 2 : 1);
    }

    private static GronnyAudioCatalogue.Step Step(float at, GardenDemoPose pose, string caption, float press = 0f) =>
        new() { at = at, pose = pose, label = caption, press = press };

    public static string VerifyImportedFiles(GronnyAudioCatalogue catalogue)
    {
        var import = JsonUtility.FromJson<Import>(File.ReadAllText("Docs/WaterSavingAudioImport.json"));
        using var hash = System.Security.Cryptography.SHA256.Create();
        string Digest(string path) => BitConverter.ToString(hash.ComputeHash(File.ReadAllBytes(path))).Replace("-", "");
        if (Digest(AssetDatabase.GetAssetPath(catalogue.Find("01_welcome").clip)) != import.welcome_sha256)
            throw new InvalidOperationException("The welcome must match the latest approved recording.");
        if (import.files.Length != 45) throw new InvalidOperationException("Expected 45 lesson recordings, including the welcome and movement feedback.");
        foreach (var file in import.files)
            if (Digest(AssetDatabase.GetAssetPath(catalogue.Find(file.id).clip)) !=
                (string.IsNullOrEmpty(file.override_sha256) ? file.source_sha256 : file.override_sha256))
                throw new InvalidOperationException("Recording does not match the supplied source: " + file.id);
        return "PASS: 45 lesson WAVs match their source or approved replacement, including the welcome and movement feedback.";
    }

    private static AudioClip LoadClip(string id)
    {
        string[] matches = AssetDatabase.FindAssets(id + " t:AudioClip", new[] { "Assets/Audio" })
            .Select(AssetDatabase.GUIDToAssetPath).Where(path => Path.GetFileNameWithoutExtension(path) == id).ToArray();
        if (matches.Length != 1) throw new InvalidOperationException("Expected exactly one supplied audio: " + id);
        return AssetDatabase.LoadAssetAtPath<AudioClip>(matches[0]);
    }

    private static float ReadWaveDuration(string path)
    {
        using var reader = new BinaryReader(File.OpenRead(path));
        reader.BaseStream.Position = 12;
        uint bytesPerSecond = 0, dataBytes = 0;
        while (reader.BaseStream.Position + 8 <= reader.BaseStream.Length)
        {
            string chunk = new(reader.ReadChars(4));
            uint size = reader.ReadUInt32();
            long start = reader.BaseStream.Position;
            if (chunk == "fmt ") { reader.BaseStream.Position = start + 8; bytesPerSecond = reader.ReadUInt32(); }
            if (chunk == "data") dataBytes = size;
            if (bytesPerSecond > 0 && dataBytes > 0) return (float)dataBytes / bytesPerSecond;
            reader.BaseStream.Position = start + size + size % 2;
        }
        throw new InvalidOperationException("Cannot read previous WAV duration: " + path);
    }
}

using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using UnityEditor;
using UnityEngine;

/// <summary>Real AudioSource continuity with synthetic action/context changes in Play.</summary>
[InitializeOnLoad]
public static class GronnyVoiceContinuityVerification
{
    private const string SessionKey = "CozyGarden.VoiceContinuityVerification";
    private static readonly List<string> checks = new();
    private static IEnumerator routine;
    private static double nextAt;
    private static double startedAt;

    static GronnyVoiceContinuityVerification() => EditorApplication.playModeStateChanged += OnPlayChanged;

    [MenuItem("Garden/Gronny/Verify voice continuity in Play")]
    public static void Begin()
    {
        if (EditorApplication.isPlayingOrWillChangePlaymode) throw new InvalidOperationException("Start outside Play.");
        if (UnityEngine.SceneManagement.SceneManager.GetActiveScene().name != "Garden_Moves")
            throw new InvalidOperationException("Open Garden_Moves first.");
        SessionState.SetBool(SessionKey, true);
        EditorApplication.isPlaying = true;
    }

    private static void OnPlayChanged(PlayModeStateChange state)
    {
        if (!SessionState.GetBool(SessionKey, false)) return;
        if (state == PlayModeStateChange.EnteredPlayMode)
        {
            checks.Clear();
            startedAt = nextAt = EditorApplication.timeSinceStartup;
            routine = Run();
            EditorApplication.update += Tick;
        }
        if (state == PlayModeStateChange.EnteredEditMode)
        {
            EditorApplication.update -= Tick;
            (routine as IDisposable)?.Dispose();
            routine = null;
            SessionState.SetBool(SessionKey, false);
        }
    }

    private static void Tick()
    {
        if (!EditorApplication.isPlaying || EditorApplication.timeSinceStartup < nextAt) return;
        try
        {
            if (EditorApplication.timeSinceStartup - startedAt > 60) throw new TimeoutException("Voice continuity verification timed out.");
            if (routine.MoveNext()) { nextAt = EditorApplication.timeSinceStartup + Convert.ToSingle(routine.Current); return; }
            Finish(null);
        }
        catch (Exception error) { Finish(error); }
    }

    private static void Finish(Exception error)
    {
        EditorApplication.update -= Tick;
        (routine as IDisposable)?.Dispose();
        routine = null;
        Directory.CreateDirectory("output");
        File.WriteAllLines("output/VoiceContinuityPlay.txt", new[]
        {
            "Unity " + Application.unityVersion, "UTC " + DateTime.UtcNow.ToString("O"),
            "Real AudioSource with synthetic relevance changes and sample seeks. Physical headset audio not tested."
        }.Concat(checks.Select(check => "PASS: " + check)).Concat(new[] { error == null ? "RESULT: PASS" : "RESULT: FAIL\n" + error }));
        if (error == null) Debug.Log("Voice continuity passed: " + checks.Count + " checks.");
        else Debug.LogError(error);
        EditorApplication.isPlaying = false;
    }

    private static IEnumerator Run()
    {
        yield return 1f;
        var rig = UnityEngine.Object.FindFirstObjectByType<OVRCameraRig>();
        rig.enabled = false;
        rig.centerEyeAnchor.position = new Vector3(0f, 1.6f, -7.88f);
        var catalogue = Resources.Load<GronnyAudioCatalogue>("GronnyAudio/Tutorial");
        var fixture = new GameObject("Voice continuity fixture (temporary)");
        try
        {
            var demo = fixture.AddComponent<GardenControlDemonstration>();
            demo.Configure(catalogue);
            demo.SetInputMode(GardenInputMode.Hands);
            var voice = fixture.AddComponent<GronnyVoicePlayer>();
            voice.Configure(catalogue, demo, menuPlayback: true);
            var source = fixture.GetComponent<AudioSource>();
            source.mute = true;

            bool actionPending = true;
            int actionStarts = 0;
            voice.Enqueue("controls_grab_hands", "action", () => actionPending, () => actionStarts++, waitForAction: true);
            yield return 0.6f;
            Check(source.isPlaying && voice.CurrentCueId == "controls_grab_hands", "A control instruction starts normally");
            source.time = 1f;
            actionPending = false;
            yield return 0.25f;
            Check(source.isPlaying && voice.CurrentCueId == "controls_grab_hands" && source.time > 1f,
                "Completing an action preserves the playing sentence instead of cutting it");
            Check(!demo.IsShowing(catalogue.Find("controls_grab_hands")), "Completed action hides its obsolete hand demonstration immediately");
            voice.Enqueue("03_plant_seed", "after-action", () => true);
            SeekToEnd(source);
            yield return 0.9f;
            Check(voice.CurrentCueId == "03_plant_seed" && actionStarts == 1, "Next instruction waits for the previous sentence and never restarts it");

            voice.Clear();
            bool pendingRelevant = true;
            voice.Enqueue("01_welcome", "ordinary", () => true);
            yield return 0.6f;
            voice.Enqueue("03_plant_seed", "stale-pending", () => pendingRelevant);
            pendingRelevant = false;
            voice.Enqueue("06_enough_water", "positive-feedback", () => true);
            yield return 0.25f;
            Check(voice.CurrentCueId == "01_welcome" && source.isPlaying, "Ordinary higher-priority feedback does not cut the welcome");
            SeekToEnd(source);
            yield return 0.9f;
            Check(voice.CurrentCueId == "06_enough_water", "Obsolete pending instructions are discarded before playback");

            voice.Clear();
            voice.Enqueue("01_welcome", "before-phase", () => true);
            yield return 0.6f;
            source.time = 1f;
            voice.Enqueue("03_plant_seed", "old-phase", () => true);
            typeof(GronnyVoicePlayer).GetMethod("FinishCurrent").Invoke(voice, null);
            voice.Enqueue("08_sprout", "new-phase", () => true);
            yield return 0.25f;
            Check(source.isPlaying && voice.CurrentCueId == "01_welcome", "Changing phase finishes the spoken sentence while clearing old queued instructions");
            SeekToEnd(source);
            yield return 0.9f;
            Check(voice.CurrentCueId == "08_sprout", "The new phase starts after the sentence finishes");

            voice.Clear();
            voice.Enqueue("controls_grab_hands", "mode-hands", () => true, waitForAction: true);
            yield return 0.6f;
            source.time = 1f;
            voice.CancelControls();
            demo.SetInputMode(GardenInputMode.Controllers);
            voice.Enqueue("controls_grab_controllers", "mode-controllers", () => true, waitForAction: true);
            yield return 0.25f;
            Check(source.isPlaying && voice.CurrentCueId == "controls_grab_hands", "Changing input mode does not sever the current phrase");
            Check(!demo.IsShowing(catalogue.Find("controls_grab_hands")), "Input change hides the previous mode's visual immediately");
            SeekToEnd(source);
            yield return 0.9f;
            Check(voice.CurrentCueId == "controls_grab_controllers", "The new input instructions follow the completed phrase");

            voice.Clear();
            int resumedStarts = 0;
            voice.Enqueue("controls_grab_controllers", "resume", () => true, () => resumedStarts++, waitForAction: true);
            yield return 0.6f;
            source.time = 1.5f;
            float interruptedAt = source.time;
            voice.Enqueue("help_excess_water", "urgent", () => true);
            yield return 0.6f;
            Check(voice.CurrentCueId == "help_excess_water", "An urgent excess-water warning can interrupt");
            SeekToEnd(source);
            yield return 0.9f;
            Check(voice.CurrentCueId == "controls_grab_controllers" && source.time >= interruptedAt - 0.05f,
                "A still-relevant interrupted instruction resumes from its saved audio position");
            Check(resumedStarts == 1, "Resuming an urgent interruption does not log another instruction start");
            voice.Clear();
            Check(!source.isPlaying && voice.CurrentCueId == null, "Explicit Stop still stops playback immediately");

            // Exercise the actual tutorial callers as well as the isolated queue.
            var menu = UnityEngine.Object.FindFirstObjectByType<GardenMenuController>();
            Call(menu, "HandleInputRelease", false, Time.unscaledTime);
            Call(menu, "HandleInputRelease", true, Time.unscaledTime);
            Call(menu, "HandleInputRelease", true, Time.unscaledTime + 0.16f);
            Call(menu, "Continue");
            Call(menu, "HandleInputRelease", true, Time.unscaledTime);
            Call(menu, "HandleInputRelease", true, Time.unscaledTime + 0.21f);
            yield return 0.6f;
            var tutorial = UnityEngine.Object.FindFirstObjectByType<GronnyTutorial>();
            var tutorialVoice = tutorial.GetComponent<GronnyVoicePlayer>();
            var tutorialAudio = tutorial.GetComponent<AudioSource>();
            tutorialAudio.mute = true;
            Check(tutorialVoice.CurrentCueId == "01_welcome", "The real tutorial begins its welcome after Play");
            tutorialAudio.time = 1f;
            Call(tutorial, "Learn", "move");
            var seeds = UnityEngine.Object.FindFirstObjectByType<SeedsController>();
            var seed = UnityEngine.Object.FindObjectsByType<SeedItem>(FindObjectsSortMode.None).First(item => item.Crop == SeedCrop.Tomato);
            var pot = UnityEngine.Object.FindObjectsByType<GardenPot>(FindObjectsSortMode.None).First(item => item.AcceptsTomato);
            GronnyTutorial.RecordSeedRelease(seed);
            seed.transform.position = pot.PlantingPoint;
            Check(seeds.TryPlant(seed), "Integration fixture plants through the real tutorial permissions");
            yield return 0.25f;
            Check(tutorialVoice.CurrentCueId == "01_welcome" && tutorialAudio.isPlaying && tutorialAudio.time > 1f,
                "The real planting phase change preserves the welcome sentence");
            seeds.ReceiveWater(pot, seeds.TargetMillilitres(seeds.PrototypeTomato) * 1.01f / 1000f);
            seeds.GetState(seeds.PrototypeTomato).lastWaterAt = Time.unscaledTime - 1f;
            yield return 0.25f;
            Check(tutorialVoice.CurrentCueId == "01_welcome" && tutorialAudio.isPlaying,
                "Reaching the actual water target queues feedback without cutting the welcome");
            SeekToEnd(tutorialAudio);
            yield return 0.9f;
            Check(tutorialVoice.CurrentCueId == "06_enough_water", "Real watering feedback follows the finished sentence");
            tutorialAudio.time = 1f;
            UnityEngine.Object.FindFirstObjectByType<CalendarVisibilityController>().Open();
            UnityEngine.Object.FindFirstObjectByType<CalendarPanel>(FindObjectsInactive.Include).AdvancePhase();
            yield return 0.25f;
            Check(seeds.Calendar.IsAdvancing && tutorialVoice.CurrentCueId == "06_enough_water" && tutorialAudio.isPlaying && tutorialAudio.time > 1f,
                "Starting the real day transition does not repeatedly clear the current audio");
        }
        finally { UnityEngine.Object.Destroy(fixture); }
    }

    private static void SeekToEnd(AudioSource source) => source.time = source.clip.length - 0.1f;
    private static void Call(object target, string method, params object[] arguments) =>
        target.GetType().GetMethod(method, BindingFlags.Instance | BindingFlags.NonPublic).Invoke(target, arguments);
    private static void Check(bool condition, string message)
    {
        if (!condition) throw new InvalidOperationException(message);
        checks.Add(message);
    }
}
